#!/usr/bin/env bash
set -Eeuo pipefail

VERSION="2026.09.23-9.9.8"
REAL_USER="${SUDO_USER:-$USER}"

if [[ "$REAL_USER" == "root" ]]; then
  echo "Execute como usuário normal, sem sudo."
  exit 1
fi

HOME_DIR="$(getent passwd "$REAL_USER" | cut -d: -f6)"
ROM_ROOT="$HOME_DIR/ROMs"
APP_DIR="$HOME_DIR/Applications"
BIN_DIR="$HOME_DIR/.local/bin"
CFG_DIR="$HOME_DIR/.config/jottabox-console"
AUTOSTART_DIR="$HOME_DIR/.config/autostart"
DESKTOP_DIR="$HOME_DIR/.local/share/applications"
STATE_DIR="$HOME_DIR/.local/share/jottabox"
ENGINE="$STATE_DIR/jottabox.sh"
ASSET_DIR="$STATE_DIR/assets"
BACKUP_DIR="$STATE_DIR/backups"
LOG_DIR="$STATE_DIR/logs"
SELF="$(readlink -f "$0")"

mkdir -p "$ROM_ROOT" "$APP_DIR" "$BIN_DIR" "$CFG_DIR" "$AUTOSTART_DIR" \
         "$DESKTOP_DIR" "$BACKUP_DIR" "$LOG_DIR" "$ASSET_DIR"

LOG="$LOG_DIR/run-$(date +%Y%m%d-%H%M%S).log"
exec > >(tee -a "$LOG") 2>&1

say(){ echo; echo ">>> $*"; }
ok(){ echo "OK: $*"; }
warn(){ echo "AVISO: $*"; }
die(){ echo "ERRO: $*" >&2; exit 1; }

ensure_dirs() {
  storage_check || return 1
  mkdir -p "$ROM_ROOT"/{nes,snes,megadrive,sega32x,segacd,saturn,mastersystem,gamegear,gb,gbc,gba,nds,n64,psx,ps2,psp,gc,wii,dreamcast,pcengine,pcenginecd,atari2600,atari5200,atari7800,atarilynx,ngp,ngpc,wonderswan,wonderswancolor,neogeo,arcade,_revisar,_arquivo}
  mkdir -p "$HOME_DIR/Downloads/rom"
}

storage_check() {
  local rom="$HOME_DIR/ROMs"
  local dl="$HOME_DIR/Downloads/rom"
  local bad=0

  if [[ -L "$rom" ]]; then
    local target
    target="$(readlink -f "$rom" 2>/dev/null || true)"
    if [[ -z "$target" || ! -d "$target" ]]; then
      bad=1
    fi
  fi

  if [[ -L "$dl" ]]; then
    local target
    target="$(readlink -f "$dl" 2>/dev/null || true)"
    if [[ -z "$target" || ! -d "$target" ]]; then
      bad=1
    fi
  fi

  if [[ "$bad" -ne 0 ]]; then
    local msg="O armazenamento externo configurado no JottaBox não está disponível. Reconecte o HD ou use 'Armazenamento' para voltar ao disco interno."
    echo "ERRO: $msg" >&2
    if [[ -n "${DISPLAY:-}" ]] && command -v zenity >/dev/null 2>&1; then
      zenity --error --title="JottaBox - HD externo ausente" --text="$msg" 2>/dev/null || true
    fi
    return 1
  fi
  return 0
}

storage_status() {
  echo
  echo "=== Armazenamento JottaBox ==="
  if [[ -L "$HOME_DIR/ROMs" ]]; then
    echo "ROMs: externo -> $(readlink "$HOME_DIR/ROMs")"
  else
    echo "ROMs: interno -> $HOME_DIR/ROMs"
  fi

  if [[ -L "$HOME_DIR/Downloads/rom" ]]; then
    echo "Downloads: externo -> $(readlink "$HOME_DIR/Downloads/rom")"
  else
    echo "Downloads: interno -> $HOME_DIR/Downloads/rom"
  fi
  echo
  df -h "$HOME_DIR" 2>/dev/null | tail -1 || true
  [[ -e "$HOME_DIR/ROMs" ]] && df -hL "$HOME_DIR/ROMs" 2>/dev/null | tail -1 || true
}

_list_external_mounts() {
  python3 - <<'PYEOF'
import json, subprocess, os
try:
    d=json.loads(subprocess.check_output(
        ["lsblk","-J","-o","PATH,TYPE,SIZE,FSTYPE,LABEL,MOUNTPOINTS,TRAN,RM,UUID"],
        text=True
    ))
except Exception:
    raise SystemExit(0)

rows=[]
def walk(nodes, inherited_tran=""):
    for n in nodes:
        tran=n.get("tran") or inherited_tran or ""
        mps=n.get("mountpoints") or []
        if isinstance(mps,str): mps=[mps]
        for mp in mps:
            if not mp or mp in ("/","/boot","/boot/efi"): continue
            # Aceita USB e volumes montados sob /media ou /mnt.
            if tran=="usb" or mp.startswith("/media/") or mp.startswith("/mnt/"):
                rows.append((
                    n.get("path") or "",
                    n.get("size") or "?",
                    n.get("fstype") or "?",
                    n.get("label") or "",
                    mp,
                    n.get("uuid") or ""
                ))
        walk(n.get("children") or [], tran)
walk(d.get("blockdevices") or [])
seen=set()
for r in rows:
    if r[4] in seen: continue
    seen.add(r[4])
    print("\t".join(str(x) for x in r))
PYEOF
}

_safe_replace_with_link() {
  local canonical="$1"
  local internal_backup="$2"
  local target="$3"
  local move_data="$4"

  mkdir -p "$target"
  mkdir -p "$(dirname "$canonical")"

  if [[ -L "$canonical" ]]; then
    rm -f "$canonical"
  elif [[ -d "$canonical" ]]; then
    if [[ "$move_data" == "yes" ]]; then
      say "Copiando $(basename "$canonical") para o HD externo"
      rsync -a --info=progress2 "$canonical/" "$target/"
      local pending
      pending="$(rsync -ani --delete "$canonical/" "$target/" | head -1 || true)"
      if [[ -n "$pending" ]]; then
        die "Validação falhou. O conteúdo interno NÃO foi removido."
      fi
      rm -rf "$canonical"
    else
      if [[ -e "$internal_backup" ]]; then
        say "Mesclando conteúdo interno preservado"
        rsync -a "$canonical/" "$internal_backup/"
        rm -rf "$canonical"
      else
        mv "$canonical" "$internal_backup"
      fi
    fi
  elif [[ -e "$canonical" ]]; then
    die "Caminho inesperado: $canonical"
  fi

  ln -s "$target" "$canonical"
}

_restore_internal_path() {
  local canonical="$1"
  local internal_backup="$2"

  if [[ -L "$canonical" ]]; then
    rm -f "$canonical"
  elif [[ -e "$canonical" ]]; then
    return 0
  fi

  if [[ -d "$internal_backup" ]]; then
    mv "$internal_backup" "$canonical"
  else
    mkdir -p "$canonical"
  fi
}

storage_manager() {
  while true; do
    clear
    storage_status
    echo "1) Usar HD externo e MOVER ROMs/Downloads para ele (libera espaço)"
    echo "2) Usar HD externo sem mover os dados internos"
    echo "3) Voltar para armazenamento interno"
    echo "4) Apenas ver discos externos disponíveis"
    echo "0) Voltar"
    echo
    read -rp "Escolha: " op

    case "$op" in
      1|2)
        mapfile -t disks < <(_list_external_mounts)
        if [[ "${#disks[@]}" -eq 0 ]]; then
          echo
          echo "Nenhum HD externo montado."
          echo "Conecte o disco, abra-o uma vez no Linux e tente novamente."
          read -rp "ENTER para continuar..." _
          continue
        fi

        echo
        echo "Discos montados:"
        local i=1
        for row in "${disks[@]}"; do
          IFS=$'\t' read -r dev size fs label mp uuid <<<"$row"
          printf "%d) %s  %s  %s  %s\n" "$i" "${label:-SEM_NOME}" "$size" "$fs" "$mp"
          ((i++))
        done
        echo "0) Cancelar"
        echo
        read -rp "Escolha o HD: " n
        [[ "$n" =~ ^[0-9]+$ ]] || continue
        [[ "$n" -gt 0 && "$n" -le "${#disks[@]}" ]] || continue

        IFS=$'\t' read -r dev size fs label mp uuid <<<"${disks[$((n-1))]}"
        [[ -d "$mp" ]] || { echo "Ponto de montagem sumiu."; sleep 2; continue; }
        [[ -w "$mp" ]] || { echo "Sem permissão de escrita em $mp"; sleep 3; continue; }

        local root="$mp/JottaBox"
        local target_rom="$root/ROMs"
        local target_dl="$root/Downloads"
        local move="no"
        [[ "$op" == "1" ]] && move="yes"

        echo
        echo "HD escolhido: ${label:-$dev}"
        echo "Destino ROMs: $target_rom"
        echo "Destino downloads: $target_dl"
        if [[ "$move" == "yes" ]]; then
          echo "Os dados serão copiados, validados e só então removidos do armazenamento interno."
        else
          echo "Os dados atuais serão preservados em pastas internas de reserva."
        fi
        read -rp "Confirmar? [s/N] " yn
        [[ "$yn" =~ ^[sSyY]$ ]] || continue

        mkdir -p "$target_rom" "$target_dl"
        _safe_replace_with_link "$HOME_DIR/ROMs" "$HOME_DIR/ROMs-interno" "$target_rom" "$move"
        _safe_replace_with_link "$HOME_DIR/Downloads/rom" "$HOME_DIR/Downloads/rom-interno" "$target_dl" "$move"

        cat > "$STATE_DIR/storage.conf" <<EOF
MODE=external
DEVICE=$dev
UUID=$uuid
MOUNTPOINT=$mp
ROM_TARGET=$target_rom
DOWNLOAD_TARGET=$target_dl
EOF
        ensure_dirs
        ok "HD externo configurado."
        storage_status
        read -rp "ENTER para continuar..." _
        ;;

      3)
        echo
        echo "Isso volta os CAMINHOS para o armazenamento interno."
        echo "Os arquivos que estiverem no HD externo continuarão preservados nele."
        read -rp "Confirmar? [s/N] " yn
        [[ "$yn" =~ ^[sSyY]$ ]] || continue

        _restore_internal_path "$HOME_DIR/ROMs" "$HOME_DIR/ROMs-interno"
        _restore_internal_path "$HOME_DIR/Downloads/rom" "$HOME_DIR/Downloads/rom-interno"
        cat > "$STATE_DIR/storage.conf" <<EOF
MODE=internal
EOF
        ensure_dirs
        ok "Armazenamento interno ativado."
        storage_status
        read -rp "ENTER para continuar..." _
        ;;

      4)
        echo
        _list_external_mounts | column -t -s $'\t' 2>/dev/null || _list_external_mounts
        echo
        read -rp "ENTER para continuar..." _
        ;;
      0) return 0 ;;
      *) ;;
    esac
  done
}

apt_base() {
  say "Instalando dependências"
  sudo apt update
  sudo apt install -y \
    curl wget ca-certificates gnupg jq git \
    flatpak unzip p7zip-full file rsync \
    libfuse2 gamemode \
    mesa-utils mesa-vulkan-drivers vulkan-tools \
    joystick jstest-gtk \
    python3 python3-pygame python3-evdev \
    xdotool zenity wget x11-xserver-utils dbus-x11
}

setup_flathub() {
  say "Configurando Flathub"
  sudo flatpak remote-add --system --if-not-exists \
    flathub https://flathub.org/repo/flathub.flatpakrepo
}

install_apps() {
  say "Instalando emuladores e Steam"
  for app in \
    org.libretro.RetroArch \
    net.pcsx2.PCSX2 \
    org.DolphinEmu.dolphin-emu \
    org.ppsspp.PPSSPP \
    com.valvesoftware.Steam
  do
    if flatpak info --system "$app" >/dev/null 2>&1; then
      ok "$app já instalado"
    else
      sudo flatpak install --system -y flathub "$app"
    fi
  done
}

install_edge() {
  if command -v microsoft-edge-stable >/dev/null 2>&1; then
    ok "Microsoft Edge já instalado"
    return
  fi

  say "Instalando Microsoft Edge"
  curl -fsSL https://packages.microsoft.com/keys/microsoft.asc \
    | gpg --dearmor \
    | sudo tee /usr/share/keyrings/microsoft-edge.gpg >/dev/null

  echo "deb [arch=amd64 signed-by=/usr/share/keyrings/microsoft-edge.gpg] https://packages.microsoft.com/repos/edge stable main" \
    | sudo tee /etc/apt/sources.list.d/microsoft-edge.list >/dev/null

  sudo apt update
  sudo apt install -y microsoft-edge-stable
}

install_esde() {
  say "Instalando/atualizando ES-DE"

  if [[ -x "$APP_DIR/ES-DE_x64.AppImage" ]]; then
    ok "ES-DE já instalado; mantendo instalação existente"
    return 0
  fi

  local json ver url tmp
  json="$(curl -fsSL https://gitlab.com/es-de/emulationstation-de/-/raw/master/latest_release.json)" || die "Falha ao consultar ES-DE"

  ver="$(printf '%s' "$json" | python3 -c 'import json,sys; print(json.load(sys.stdin)["stable"]["version"])')" || true
  url="$(printf '%s' "$json" | python3 -c '
import json,sys
d=json.load(sys.stdin)
for p in d["stable"]["packages"]:
    fn=(p.get("filename") or "").lower()
    name=(p.get("name") or "").lower()
    url=p.get("url") or ""
    if ("appimage" in fn or "appimage" in name) and ("x64" in fn or "x86_64" in fn or "linux" in name) and "aarch64" not in fn and "arm" not in fn:
        print(url); break
')" || true

  [[ -n "$url" ]] || die "Não localizei o AppImage x64 do ES-DE"

  tmp="$(mktemp)"
  curl -fL "$url" -o "$tmp"
  chmod +x "$tmp"

  if [[ -f "$APP_DIR/ES-DE_x64.AppImage" ]]; then
    cp -a "$APP_DIR/ES-DE_x64.AppImage" "$BACKUP_DIR/ES-DE.$(date +%Y%m%d-%H%M%S).bak"
  fi

  mv "$tmp" "$APP_DIR/ES-DE_x64.AppImage"
  chmod +x "$APP_DIR/ES-DE_x64.AppImage"
  ok "ES-DE $ver instalado"
}

install_cores() {
  say "Instalando cores recomendados do RetroArch"

  local core_dir tmp src archive_ok url
  core_dir="$HOME_DIR/.var/app/org.libretro.RetroArch/config/retroarch/cores"
  mkdir -p "$core_dir"

  local cores=(
    nestopia_libretro.so
    fceumm_libretro.so
    snes9x_libretro.so
    genesis_plus_gx_libretro.so
    picodrive_libretro.so
    gambatte_libretro.so
    mgba_libretro.so
    mupen64plus_next_libretro.so
    swanstation_libretro.so
    pcsx_rearmed_libretro.so
    fbneo_libretro.so
  )

  local missing=()
  for core in "${cores[@]}"; do
    if [[ ! -s "$core_dir/$core" ]]; then
      missing+=("$core")
    fi
  done

  if [[ "${#missing[@]}" -eq 0 ]]; then
    ok "Todos os cores recomendados já estão instalados; pulando download"
    return 0
  fi

  echo "Cores ausentes: ${missing[*]}"
  tmp="$(mktemp -d)"
  trap 'rm -rf "$tmp"' RETURN

  archive_ok=0

  # Nightly primeiro. Alguns dias o servidor publica um arquivo inválido/pequeno,
  # por isso validamos tamanho e integridade antes de usar.
  for url in \
    "https://buildbot.libretro.com/nightly/linux/x86_64/RetroArch_cores.7z" \
    "https://buildbot.libretro.com/stable/1.22.0/linux/x86_64/RetroArch_cores.7z"
  do
    echo "Tentando: $url"
    rm -f "$tmp/cores.7z"

    if curl -fL --retry 2 --connect-timeout 15 "$url" -o "$tmp/cores.7z"; then
      size="$(stat -c '%s' "$tmp/cores.7z" 2>/dev/null || echo 0)"
      if [[ "$size" -gt 1000000 ]] && 7z t "$tmp/cores.7z" >/dev/null 2>&1; then
        archive_ok=1
        break
      fi
      warn "Pacote de cores inválido ou incompleto ($size bytes)"
    fi
  done

  if [[ "$archive_ok" -ne 1 ]]; then
    warn "Não consegui baixar um pacote válido de cores."
    warn "O restante da instalação continuará; cores já existentes serão preservados."
    rm -rf "$tmp"
    trap - RETURN
    return 0
  fi

  mkdir -p "$tmp/out"
  7z x -y "$tmp/cores.7z" "-o$tmp/out" >/dev/null

  for core in "${missing[@]}"; do
    src="$(find "$tmp/out" -type f -name "$core" -print -quit)"
    if [[ -n "${src:-}" ]]; then
      cp -f "$src" "$core_dir/$core"
      echo " + $core"
    else
      warn "Não encontrado no pacote: $core"
    fi
  done

  rm -rf "$tmp"
  trap - RETURN
}


configure_retroarch() {
  say "Configurando RetroArch"
  local cfg="$HOME_DIR/.var/app/org.libretro.RetroArch/config/retroarch/retroarch.cfg"
  mkdir -p "$(dirname "$cfg")"
  touch "$cfg"

  set_cfg() {
    local k="$1" v="$2"
    sed -i "/^[[:space:]]*${k}[[:space:]]*=/d" "$cfg"
    echo "$k = \"$v\"" >> "$cfg"
  }

  set_cfg video_fullscreen true
  set_cfg video_windowed_fullscreen true
  set_cfg menu_show_core_updater true

  # Xbox/SDL normalmente usa Back/Select=6 e Start=7.
  # O daemon global abaixo é a proteção principal; estes valores
  # também deixam o RetroArch sair diretamente com Select+Start.
  set_cfg input_enable_hotkey_btn 6
  set_cfg input_exit_emulator_btn 7
}

install_engine() {
  say "Instalando motor permanente do JottaBox"

  mkdir -p "$STATE_DIR"

  local self_real engine_real
  self_real="$(readlink -f "$SELF")"
  engine_real="$(readlink -f "$ENGINE" 2>/dev/null || printf '%s' "$ENGINE")"

  # Se estamos executando a partir de /tmp, Downloads etc., guarda uma cópia
  # permanente. Se já estamos executando o próprio motor, não copia sobre si.
  if [[ "$self_real" != "$engine_real" ]]; then
    local tmp_engine="$ENGINE.tmp.$$"
    cp -f "$SELF" "$tmp_engine"
    chmod 755 "$tmp_engine"
    mv -f "$tmp_engine" "$ENGINE"
  else
    chmod 755 "$ENGINE"
  fi

  [[ -x "$ENGINE" ]] || die "Falha ao instalar motor permanente: $ENGINE"

  # Validação básica antes de criar atalhos.
  bash -n "$ENGINE" || die "Motor permanente contém erro de sintaxe"
  ok "Motor permanente: $ENGINE"
}

create_wrappers() {
  say "Criando atalhos"

  cat > "$BIN_DIR/gpbox" <<'EOF'
#!/usr/bin/env bash
export PATH="/var/lib/flatpak/exports/bin:$HOME/.local/share/flatpak/exports/bin:$PATH"
APP="$HOME/Applications/ES-DE_x64.AppImage"
"$HOME/.local/share/jottabox/jottabox.sh" storage-check || exit 1
if [[ -x "$APP" ]]; then
  exec gamemoderun "$APP"
fi
zenity --error --title="JottaBox / ES-DE" --text="ES-DE não encontrado em:\n$APP"
EOF
  chmod +x "$BIN_DIR/gpbox"

  cat > "$BIN_DIR/xbox-cloud" <<'EOF'
#!/usr/bin/env bash
EDGE="$(command -v microsoft-edge-stable || command -v microsoft-edge || true)"
[[ -n "$EDGE" ]] || { zenity --error --text="Microsoft Edge não encontrado."; exit 1; }
PROFILE="$HOME/.config/jottabox-edge-xcloud"
mkdir -p "$PROFILE"
exec "$EDGE" \
  --user-data-dir="$PROFILE" \
  --start-fullscreen \
  --no-first-run \
  --disable-session-crashed-bubble \
  --disable-background-mode \
  --disable-features=msEdgeStartupBoost \
  --app="https://www.xbox.com/play"
EOF
  chmod +x "$BIN_DIR/xbox-cloud"

  cat > "$BIN_DIR/jottabox-import-roms" <<EOF
#!/usr/bin/env bash
exec "$ENGINE" import "\${1:-\$HOME/Downloads/rom}"
EOF
  chmod +x "$BIN_DIR/jottabox-import-roms"

  cat > "$BIN_DIR/jottabox-clean-roms" <<EOF
#!/usr/bin/env bash
exec "$ENGINE" clean all
EOF
  chmod +x "$BIN_DIR/jottabox-clean-roms"

  cat > "$BIN_DIR/jottabox-update" <<EOF
#!/usr/bin/env bash
exec "$ENGINE" update
EOF
  chmod +x "$BIN_DIR/jottabox-update"

  cat > "$BIN_DIR/jottabox-download-roms" <<EOF
#!/usr/bin/env bash
"$ENGINE" storage-check || exit 1
exec /usr/bin/python3 "$CFG_DIR/downloader_gui.py"
EOF
  chmod +x "$BIN_DIR/jottabox-download-roms"

  cat > "$BIN_DIR/jottabox-status" <<EOF
#!/usr/bin/env bash
exec "$ENGINE" status
EOF
  chmod +x "$BIN_DIR/jottabox-status"

  cat > "$BIN_DIR/jottabox-repair-hotkey" <<EOF
#!/usr/bin/env bash
exec "$ENGINE" repair-hotkey
EOF
  chmod +x "$BIN_DIR/jottabox-repair-hotkey"

  cat > "$BIN_DIR/jottabox-storage" <<EOF
#!/usr/bin/env bash
exec "$ENGINE" storage
EOF
  chmod +x "$BIN_DIR/jottabox-storage"

  ln -sf "$BIN_DIR/jottabox-console" "$BIN_DIR/m720q-console"
  ln -sf "$BIN_DIR/jottabox-import-roms" "$BIN_DIR/m720q-import-roms"
  ln -sf "$BIN_DIR/jottabox-clean-roms" "$BIN_DIR/m720q-clean-roms"
  ln -sf "$BIN_DIR/jottabox-update" "$BIN_DIR/m720q-update"
}


create_hotkey_watchdog() {
  say "Configurando saída de emergência SELECT + START"

  cat > "$BIN_DIR/jottabox-hotkeys" <<'PYEOF'
#!/usr/bin/env python3
import os
import time
import select
import subprocess
from evdev import InputDevice, list_devices, ecodes

pressed = {}
last_trigger = 0.0
devices = {}

TARGET_FLATPAKS = [
    "org.libretro.RetroArch",
    "net.pcsx2.PCSX2",
    "org.DolphinEmu.dolphin-emu",
    "org.ppsspp.PPSSPP",
]

TARGET_PROCESSES = [
    "retroarch",
    "pcsx2-qt",
    "PCSX2",
    "dolphin-emu",
    "PPSSPPSDL",
    "PPSSPPQt",
]

def log(msg):
    try:
        os.makedirs(os.path.expanduser("~/.local/share/jottabox/logs"), exist_ok=True)
        with open(os.path.expanduser("~/.local/share/jottabox/logs/hotkeys.log"), "a") as f:
            f.write(time.strftime("%F %T ") + msg + "\n")
    except Exception:
        pass

def rescan():
    global devices, pressed
    new = {}
    for path in list_devices():
        try:
            d = InputDevice(path)
            caps = d.capabilities().get(ecodes.EV_KEY, [])
            # Gamepads normalmente anunciam BTN_GAMEPAD/BTN_SOUTH/BTN_A.
            if any(code in caps for code in (
                ecodes.BTN_GAMEPAD, ecodes.BTN_SOUTH, ecodes.BTN_A,
                ecodes.BTN_JOYSTICK
            )):
                new[d.fd] = d
                pressed.setdefault(d.path, set())
        except Exception:
            pass

    # Fecha descritores que sumiram.
    for fd,d in list(devices.items()):
        if fd not in new:
            try: d.close()
            except Exception: pass

    devices = new

def emulator_running():
    try:
        out = subprocess.check_output(["flatpak","ps","--columns=application"], text=True, stderr=subprocess.DEVNULL)
        if any(app in out for app in TARGET_FLATPAKS):
            return True
    except Exception:
        pass

    for proc in TARGET_PROCESSES:
        if subprocess.run(["pgrep","-f",proc], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0:
            return True
    return False

def close_emulators():
    log("SELECT+START acionado")
    for app in TARGET_FLATPAKS:
        subprocess.run(["flatpak","kill",app], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    for proc in TARGET_PROCESSES:
        subprocess.run(["pkill","-TERM","-f",proc], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def return_to_jottabox():
    # Fecha também o ES-DE. O launcher JottaBox está aguardando o processo
    # gpbox terminar; ao fechar o ES-DE, ele retoma automaticamente.
    time.sleep(0.45)
    subprocess.run(
        ["pkill","-TERM","-f","ES-DE_x64.AppImage"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL
    )
    time.sleep(0.8)

    try:
        ids = subprocess.check_output(
            ["xdotool","search","--name","JottaBox"],
            text=True,
            stderr=subprocess.DEVNULL
        ).split()
        if ids:
            subprocess.run(
                ["xdotool","windowactivate","--sync",ids[-1]],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL
            )
    except Exception:
        pass
    log("retorno direto ao JottaBox")

def trigger():
    global last_trigger
    now = time.monotonic()
    if now - last_trigger < 2.0:
        return
    last_trigger = now

    if not emulator_running():
        return

    close_emulators()
    return_to_jottabox()

rescan()
last_scan = time.monotonic()

while True:
    now = time.monotonic()
    if now - last_scan > 3:
        rescan()
        last_scan = now

    if not devices:
        time.sleep(1)
        continue

    try:
        readable,_,_ = select.select(list(devices.values()), [], [], 1.0)
    except Exception:
        rescan()
        continue

    for dev in readable:
        try:
            for event in dev.read():
                if event.type != ecodes.EV_KEY:
                    continue

                keys = pressed.setdefault(dev.path, set())
                if event.value in (1,2):
                    keys.add(event.code)
                elif event.value == 0:
                    keys.discard(event.code)

                # BTN_SELECT + BTN_START é o padrão Linux/evdev
                # para Back/Select + Start em controles Xbox/PS.
                if ecodes.BTN_SELECT in keys and ecodes.BTN_START in keys:
                    trigger()
        except OSError:
            rescan()
            break
        except Exception as e:
            log("erro: " + repr(e))
PYEOF

  chmod +x "$BIN_DIR/jottabox-hotkeys"

  cat > "$AUTOSTART_DIR/jottabox-hotkeys.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=JottaBox Hotkeys
Comment=SELECT + START fecha o emulador e retorna ao JottaBox
Exec=$BIN_DIR/jottabox-hotkeys
Terminal=false
X-GNOME-Autostart-enabled=true
Hidden=false
EOF

  # Inicia já na sessão atual se ainda não estiver rodando.
  if ! pgrep -f "$BIN_DIR/jottabox-hotkeys" >/dev/null 2>&1; then
    nohup "$BIN_DIR/jottabox-hotkeys" >/dev/null 2>&1 &
  fi
}


