create_downloader_gui() {
  say "Criando navegador de downloads JottaBox"

  cat > "$CFG_DIR/downloader_gui.py" <<'PYEOF'
#!/usr/bin/env python3
import os, re, sys, json, time, html, traceback, subprocess
import urllib.parse, urllib.request
import pygame

pygame.init()
pygame.joystick.init()

HOME=os.path.expanduser("~")
CFG=os.path.join(HOME,".config","jottabox-console")
STATE=os.path.join(HOME,".local","share","jottabox")
ASSETS=os.path.join(STATE,"assets")
DEST=os.path.join(HOME,"Downloads","rom")
LOG=os.path.join(HOME,"jotabox-download.log")
GUI_LOG=os.path.join(HOME,"jotabox-downloader-gui.log")
LAST=os.path.join(CFG,"last-download.json")
os.makedirs(CFG,exist_ok=True)
os.makedirs(DEST,exist_ok=True)

def crashhook(t,v,tb):
    try:
        with open(GUI_LOG,"a") as f:
            f.write("\n===== CRASH GUI =====\n")
            traceback.print_exception(t,v,tb,file=f)
    except Exception:
        pass
    sys.__excepthook__(t,v,tb)
sys.excepthook=crashhook

INFO=pygame.display.Info()
W,H=INFO.current_w,INFO.current_h
screen=pygame.display.set_mode((W,H),pygame.FULLSCREEN|pygame.DOUBLEBUF)
pygame.display.set_caption("JottaBox - Downloads")
pygame.mouse.set_visible(False)
clock=pygame.time.Clock()

WHITE=(246,249,255); MUTED=(164,184,210); CYAN=(24,213,255)
GREEN=(21,230,126); RED=(255,70,78); AMBER=(255,190,84)
PANEL=(4,17,38,225)

def font(size,b=False): return pygame.font.SysFont("DejaVu Sans",size,bold=b)
F_LOGO=font(max(44,int(H*.056)),True)
F_TITLE=font(max(26,int(H*.032)),True)
F_CARD=font(max(19,int(H*.024)),True)
F_BODY=font(max(15,int(H*.020)))
F_SMALL=font(max(13,int(H*.017)))
def txt(s,f,c=WHITE): return f.render(str(s),True,c)

def load_bg():
    try:
        img=pygame.image.load(os.path.join(ASSETS,"wallpaper.png")).convert()
        return pygame.transform.smoothscale(img,(W,H))
    except Exception: return None
BG=load_bg()

def draw_bg():
    if BG: screen.blit(BG,(0,0))
    else: screen.fill((3,12,28))
    ov=pygame.Surface((W,H),pygame.SRCALPHA); ov.fill((0,7,20,95)); screen.blit(ov,(0,0))

def alpha_rect(r,color,radius=20):
    s=pygame.Surface((r.w,r.h),pygame.SRCALPHA)
    pygame.draw.rect(s,color,s.get_rect(),border_radius=radius); screen.blit(s,r.topleft)

def header(title,subtitle=""):
    m=int(W*.06)
    a=txt("Jotta",F_LOGO); b=txt("Box",F_LOGO,CYAN)
    screen.blit(a,(m,int(H*.035))); screen.blit(b,(m+a.get_width()-3,int(H*.035)))
    screen.blit(txt(title,F_TITLE),(m,int(H*.14)))
    if subtitle: screen.blit(txt(subtitle,F_BODY,MUTED),(m,int(H*.185)))

def footer(s):
    r=txt(s,F_SMALL,MUTED); screen.blit(r,((W-r.get_width())//2,H-int(H*.05)))

ALLOWED={
 ".zip",".7z",".nes",".sfc",".smc",".gb",".gbc",".gba",".nds",
 ".n64",".z64",".v64",".md",".gen",".smd",".32x",".sms",".gg",
 ".pce",".a26",".a52",".a78",".lnx",".ngp",".ngc",".ws",".wsc",
 ".cue",".bin",".gdi",".chd",".iso",".cso",".pbp",".cdi",
 ".rvz",".gcm",".gcz",".wbfs"
}

def normalize_root(url):
    url=url.strip()
    if not url.endswith("/"): url+="/"
    p=urllib.parse.urlparse(url)
    if p.scheme not in ("http","https") or not p.netloc:
        raise ValueError("URL inválida")
    return url

def get_html(url):
    req=urllib.request.Request(url,headers={"User-Agent":"JottaBox/1.0"})
    with urllib.request.urlopen(req,timeout=30) as r:
        return r.read().decode("utf-8","ignore")

def fetch_entries(root):
    data=get_html(root)
    hrefs=re.findall(r'href=["\']([^"\']+)["\']',data,re.I)
    rp=urllib.parse.urlparse(root)
    result=[]; seen=set()
    for href in hrefs:
        href=html.unescape(href)
        if href in ("../","./","/"): continue
        full=urllib.parse.urljoin(root,href)
        p=urllib.parse.urlparse(full)
        if p.netloc!=rp.netloc: continue
        if not full.startswith(root): continue
        rel=urllib.parse.unquote(full[len(root):]).strip("/")
        if not rel or "/" in rel: continue
        is_dir=href.endswith("/")
        name=urllib.parse.unquote(rel)
        if not is_dir and os.path.splitext(name)[1].lower() not in ALLOWED:
            continue
        item={"name":name,"url":full if not is_dir or full.endswith("/") else full+"/",
              "kind":"dir" if is_dir else "file"}
        key=(item["url"],item["kind"])
        if key not in seen:
            seen.add(key); result.append(item)
    result.sort(key=lambda e:(0 if e["kind"]=="dir" else 1,e["name"].lower()))
    return result

def crawl_files(folder_url, base_root, progress_cb=None):
    """Recursively parse directory indexes and return concrete file URLs."""
    todo=[folder_url]; seen_dirs=set(); files=[]; seen_files=set()
    root_host=urllib.parse.urlparse(base_root).netloc
    while todo:
        url=todo.pop()
        if url in seen_dirs: continue
        seen_dirs.add(url)
        if progress_cb: progress_cb(f"Lendo pasta {urllib.parse.unquote(url.rstrip('/').split('/')[-1])}...")
        try: data=get_html(url)
        except Exception as e:
            with open(LOG,"a") as log: log.write(f"\nERRO listando {url}: {e}\n")
            continue
        for href in re.findall(r'href=["\']([^"\']+)["\']',data,re.I):
            href=html.unescape(href)
            if href in ("../","./","/") or href.startswith("?"): continue
            full=urllib.parse.urljoin(url,href)
            p=urllib.parse.urlparse(full)
            if p.netloc!=root_host: continue
            # nunca sobe para fora da pasta selecionada
            if not full.startswith(folder_url): continue
            if href.endswith("/"):
                if full not in seen_dirs: todo.append(full)
            else:
                name=urllib.parse.unquote(p.path.rsplit("/",1)[-1])
                if os.path.splitext(name)[1].lower() in ALLOWED and full not in seen_files:
                    seen_files.add(full); files.append(full)
    return files

def dest_for_url(url, base_root):
    rp=urllib.parse.urlparse(base_root)
    up=urllib.parse.urlparse(url)
    base_path=rp.path
    rel=urllib.parse.unquote(up.path[len(base_path):]).lstrip("/") if up.path.startswith(base_path) else urllib.parse.unquote(up.path).lstrip("/")
    rel=rel.replace("..","_")
    return os.path.join(DEST,rel)

def download_file(url, base_root, label_cb=None):
    dest=dest_for_url(url,base_root)
    os.makedirs(os.path.dirname(dest),exist_ok=True)
    if label_cb: label_cb("Baixando "+os.path.basename(dest))
    cmd=["wget","--continue","--tries=3","--timeout=30","--read-timeout=30","--waitretry=5","-O",dest,url]
    with open(LOG,"a") as log:
        log.write(f"\n===== ARQUIVO {url} =====\n")
        p=subprocess.run(cmd,stdout=log,stderr=subprocess.STDOUT)
    return p.returncode

def progress_screen(label,done=0,total=0):
    draw_bg(); header("Downloads",label)
    w=int(W*.68); h=36; x=(W-w)//2; y=int(H*.5)
    alpha_rect(pygame.Rect(x,y,w,h),(4,18,40,220),18)
    pct=(done/total) if total else 0
    pygame.draw.rect(screen,CYAN,(x,y,int(w*max(0,min(1,pct))),h),border_radius=18)
    if total:
        s=txt(f"{done}/{total}",F_BODY); screen.blit(s,((W-s.get_width())//2,y+55))
    pygame.display.flip(); pygame.event.pump()

def run_download(root,selected):
    allfiles=[]
    for e in selected:
        if e["kind"]=="file":
            allfiles.append(e["url"])
        else:
            found=crawl_files(e["url"],root,lambda s:progress_screen(s))
            allfiles.extend(found)
    # preserva ordem e remove duplicatas
    allfiles=list(dict.fromkeys(allfiles))
    if not allfiles:
        return False,"Nenhum arquivo compatível encontrado."

    errors=[]
    for i,url in enumerate(allfiles,1):
        progress_screen("Baixando "+urllib.parse.unquote(url.rsplit("/",1)[-1]),i-1,len(allfiles))
        rc=download_file(url,root)
        if rc not in (0,8):
            errors.append((url,rc))
    progress_screen("Downloads finalizados",len(allfiles),len(allfiles))
    if errors:
        return False,f"{len(errors)} arquivo(s) falharam. Veja o log."
    return True,f"{len(allfiles)} arquivo(s) processados."

def load_last():
    try: return json.load(open(LAST))
    except Exception: return {"root_url":"","selected":[]}

def save_last(root,selected):
    try:
        with open(LAST,"w") as f: json.dump({"root_url":root,"selected":selected},f)
    except Exception: pass

def keyboard_url(current):
    val=current; active=True
    while active:
        draw_bg(); header("Downloads","Digite a URL da fonte autorizada")
        r=pygame.Rect(int(W*.08),int(H*.38),int(W*.84),int(H*.10))
        alpha_rect(r,(4,18,40,230))
        screen.blit(txt(val[-110:],F_BODY),(r.x+20,r.y+25))
        footer("ENTER Confirmar    ESC Cancelar")
        pygame.display.flip()
        for e in pygame.event.get():
            if e.type==pygame.KEYDOWN:
                if e.key==pygame.K_RETURN: active=False
                elif e.key==pygame.K_ESCAPE: return current
                elif e.key==pygame.K_BACKSPACE: val=val[:-1]
                elif e.unicode and e.unicode.isprintable(): val+=e.unicode
        clock.tick(60)
    return val

state=load_last()
root=state.get("root_url","")
selected_names=set(state.get("selected",[]))
entries=[]; cursor=0; scroll=0; message=""; mode="url"

def load_entries():
    global entries,cursor,scroll,message,mode,root
    try:
        root=normalize_root(root)
        progress_screen("Lendo lista...")
        entries=fetch_entries(root)
        cursor=scroll=0
        message=f"{sum(e['kind']=='dir' for e in entries)} pasta(s), {sum(e['kind']=='file' for e in entries)} arquivo(s)"
        mode="browse"
    except Exception as e:
        message=f"Erro: {e}"
        mode="url"

running=True
while running:
    draw_bg()
    if mode=="url":
        header("Downloads","Tudo será salvo em ~/Downloads/rom. Depois use Importar Jogos.")
        r=pygame.Rect(int(W*.08),int(H*.38),int(W*.84),int(H*.10))
        alpha_rect(r,PANEL)
        screen.blit(txt(root or "Informe a URL...",F_BODY),(r.x+20,r.y+25))
        if message: screen.blit(txt(message,F_SMALL,AMBER),(r.x,r.bottom+25))
        footer("ENTER Editar URL    F10 Continuar    ESC Voltar")
    else:
        header("Downloads",message or "Selecione o que deseja baixar")
        top=int(H*.245); rh=int(H*.072); shown=7
        if cursor<scroll: scroll=cursor
        if cursor>=scroll+shown: scroll=cursor-shown+1
        for line,idx in enumerate(range(scroll,min(len(entries),scroll+shown))):
            e=entries[idx]; r=pygame.Rect(int(W*.10),top+line*rh,int(W*.80),rh-8)
            alpha_rect(r,(8,29,57,235) if idx==cursor else (4,18,40,215))
            if idx==cursor: pygame.draw.rect(screen,CYAN,r,3,border_radius=18)
            mark="☑" if e["name"] in selected_names else "☐"
            kind="PASTA" if e["kind"]=="dir" else "ARQUIVO"
            screen.blit(txt(f"{mark}  {kind}  {e['name']}",F_CARD),(r.x+18,r.y+13))
        footer("ENTER Marcar    X Todos    Y Limpar    F10 Baixar    ESC Voltar")
    pygame.display.flip()

    for ev in pygame.event.get():
        if ev.type==pygame.QUIT: running=False
        elif ev.type==pygame.KEYDOWN:
            if mode=="url":
                if ev.key in (pygame.K_RETURN,pygame.K_SPACE):
                    root=keyboard_url(root)
                elif ev.key==pygame.K_F10:
                    load_entries()
                elif ev.key==pygame.K_ESCAPE:
                    running=False
            else:
                if ev.key in (pygame.K_UP,pygame.K_LEFT):
                    cursor=(cursor-1)%len(entries) if entries else 0
                elif ev.key in (pygame.K_DOWN,pygame.K_RIGHT):
                    cursor=(cursor+1)%len(entries) if entries else 0
                elif ev.key in (pygame.K_RETURN,pygame.K_SPACE) and entries:
                    n=entries[cursor]["name"]
                    if n in selected_names: selected_names.remove(n)
                    else: selected_names.add(n)
                elif ev.key==pygame.K_x:
                    selected_names={e["name"] for e in entries}
                elif ev.key==pygame.K_y:
                    selected_names.clear()
                elif ev.key==pygame.K_F10:
                    chosen=[e for e in entries if e["name"] in selected_names]
                    if chosen:
                        save_last(root,list(selected_names))
                        ok,msg=run_download(root,chosen)
                        message=("Concluído. Agora use IMPORTAR JOGOS. " if ok else "Falha. ")+msg
                    else:
                        message="Marque pelo menos um item."
                elif ev.key==pygame.K_ESCAPE:
                    mode="url"

        elif ev.type==pygame.JOYBUTTONDOWN:
            # A=0, B=1, X=2, Y=3, START geralmente 7
            if mode=="url":
                if ev.button==0: root=keyboard_url(root)
                elif ev.button in (7,9): load_entries()
                elif ev.button==1: running=False
            else:
                if ev.button==0 and entries:
                    n=entries[cursor]["name"]
                    if n in selected_names: selected_names.remove(n)
                    else: selected_names.add(n)
                elif ev.button==2:
                    selected_names={e["name"] for e in entries}
                elif ev.button==3:
                    selected_names.clear()
                elif ev.button in (7,9):
                    chosen=[e for e in entries if e["name"] in selected_names]
                    if chosen:
                        save_last(root,list(selected_names))
                        ok,msg=run_download(root,chosen)
                        message=("Concluído. Agora use IMPORTAR JOGOS. " if ok else "Falha. ")+msg
                elif ev.button==1:
                    mode="url"

        elif ev.type==pygame.JOYHATMOTION and mode=="browse" and entries:
            if ev.value[1]>0: cursor=(cursor-1)%len(entries)
            elif ev.value[1]<0: cursor=(cursor+1)%len(entries)

    clock.tick(60)

pygame.quit()
PYEOF

  chmod +x "$CFG_DIR/downloader_gui.py"
}

create_controller_wizard() {
  say "Criando assistente de configuração de controle"

  cat > "$CFG_DIR/controller_wizard.py" <<'PYEOF'
#!/usr/bin/env python3
import os, sys, time, json, traceback, pygame

pygame.init()
pygame.joystick.init()

HOME=os.path.expanduser("~")
RA_DIR=os.path.join(HOME,".var","app","org.libretro.RetroArch","config","retroarch")
AUTO=os.path.join(RA_DIR,"autoconfig","udev")
CFG=os.path.join(RA_DIR,"retroarch.cfg")
LOG=os.path.join(HOME,"jottabox-controller-wizard.log")
os.makedirs(AUTO,exist_ok=True)

INFO=pygame.display.Info()
W,H=INFO.current_w,INFO.current_h
screen=pygame.display.set_mode((W,H),pygame.FULLSCREEN|pygame.DOUBLEBUF)
pygame.display.set_caption("JottaBox - Configurar controle")
pygame.mouse.set_visible(False)
clock=pygame.time.Clock()

WHITE=(245,249,255); MUTED=(162,187,219); CYAN=(26,213,255)
GREEN=(26,224,121); AMBER=(255,190,72); RED=(255,76,82)
BG=(3,12,28)

def font(sz,b=False):
    return pygame.font.SysFont("DejaVu Sans",sz,bold=b)

F1=font(max(38,int(H*.05)),True)
F2=font(max(24,int(H*.032)),True)
F3=font(max(17,int(H*.022)))
F4=font(max(14,int(H*.018)))

def txt(s,f,c=WHITE): return f.render(str(s),True,c)

def draw_bg():
    screen.fill(BG)
    pygame.draw.circle(screen,(7,39,78),(int(W*.82),int(H*.2)),int(H*.34))
    pygame.draw.circle(screen,(4,24,52),(int(W*.18),int(H*.85)),int(H*.42))

def center(s,y):
    screen.blit(s,((W-s.get_width())//2,y))

def header(title,sub=""):
    draw_bg()
    a=txt("Jotta",F1,WHITE); b=txt("Box",F1,CYAN)
    x=int(W*.06); y=int(H*.04)
    screen.blit(a,(x,y)); screen.blit(b,(x+a.get_width()-3,y))
    center(txt(title,F2,WHITE),int(H*.18))
    if sub: center(txt(sub,F3,MUTED),int(H*.235))

def message(title,body,color=WHITE,footer="ENTER continuar   ESC sair"):
    header(title)
    center(txt(body,F2,color),int(H*.43))
    center(txt(footer,F4,MUTED),int(H*.88))
    pygame.display.flip()

def wait_enter():
    while True:
        for e in pygame.event.get():
            if e.type==pygame.KEYDOWN:
                if e.key==pygame.K_ESCAPE: return False
                if e.key in (pygame.K_RETURN,pygame.K_SPACE): return True
            elif e.type==pygame.JOYBUTTONDOWN:
                return True
        clock.tick(60)

def refresh_joy():
    pygame.joystick.quit(); pygame.joystick.init()
    arr=[]
    for i in range(pygame.joystick.get_count()):
        j=pygame.joystick.Joystick(i); j.init(); arr.append(j)
    return arr

def choose_joystick():
    joys=refresh_joy()
    if not joys:
        message("Configurar controle","Nenhum controle encontrado",RED,"Conecte o controle e pressione ENTER para tentar novamente")
        if wait_enter():
            joys=refresh_joy()
    if not joys: return None
    if len(joys)==1: return joys[0]

    idx=0
    while True:
        header("Escolha o controle","Use ↑ ↓ e ENTER")
        top=int(H*.34)
        for n,j in enumerate(joys):
            c=CYAN if n==idx else WHITE
            center(txt(("> " if n==idx else "  ")+j.get_name(),F2,c),top+n*55)
        pygame.display.flip()
        for e in pygame.event.get():
            if e.type==pygame.KEYDOWN:
                if e.key==pygame.K_ESCAPE:return None
                if e.key==pygame.K_UP:idx=(idx-1)%len(joys)
                if e.key==pygame.K_DOWN:idx=(idx+1)%len(joys)
                if e.key in (pygame.K_RETURN,pygame.K_SPACE): return joys[idx]
            elif e.type==pygame.JOYBUTTONDOWN:
                return joys[e.joy] if e.joy < len(joys) else joys[0]
        clock.tick(60)

def neutral_axes(j):
    vals={}
    for a in range(j.get_numaxes()):
        try: vals[a]=j.get_axis(a)
        except: vals[a]=0.0
    return vals

def capture(j,label,allow_hat=True,allow_axis=True):
    base=neutral_axes(j)
    # drain events
    pygame.event.clear()
    started=time.monotonic()
    while True:
        header("Configurar controle",f"Controle: {j.get_name()}")
        center(txt(f"Pressione: {label}",F1,CYAN),int(H*.43))
        center(txt("ESC = cancelar   BACKSPACE = pular",F4,MUTED),int(H*.88))
        pygame.display.flip()

        for e in pygame.event.get():
            if e.type==pygame.KEYDOWN:
                if e.key==pygame.K_ESCAPE: return "CANCEL",None
                if e.key==pygame.K_BACKSPACE: return "SKIP",None
            elif e.type==pygame.JOYBUTTONDOWN and e.joy==j.get_id():
                return "BTN",e.button
            elif allow_hat and e.type==pygame.JOYHATMOTION and e.joy==j.get_id():
                x,y=e.value
                if y>0:return "HAT","h0up"
                if y<0:return "HAT","h0down"
                if x<0:return "HAT","h0left"
                if x>0:return "HAT","h0right"
            elif allow_axis and e.type==pygame.JOYAXISMOTION and e.joy==j.get_id():
                prev=base.get(e.axis,0.0)
                if abs(e.value-prev)>.65 and abs(e.value)>.65:
                    sign="+" if e.value>0 else "-"
                    return "AXIS",f"{sign}{e.axis}"
        clock.tick(60)

def capture_axis_direction(j,label,axis_hint=None):
    return capture(j,label,allow_hat=False,allow_axis=True)

def cfg_line(key,kind,val):
    if kind=="BTN":
        return f'{key}_btn = "{val}"'
    if kind=="HAT":
        return f'{key}_btn = "{val}"'
    if kind=="AXIS":
        return f'{key}_axis = "{val}"'
    return None

j=choose_joystick()
if not j:
    pygame.quit(); sys.exit(1)

message("Configurar controle",j.get_name(),GREEN,"Pressione qualquer botão para começar")
if not wait_enter():
    pygame.quit(); sys.exit(0)

steps=[
 ("input_b","A / botão inferior",True,True),
 ("input_a","B / botão direito",True,True),
 ("input_y","X / botão esquerdo",True,True),
 ("input_x","Y / botão superior",True,True),
 ("input_select","SELECT / SHARE / BACK",False,False),
 ("input_start","START / OPTIONS",False,False),
 ("input_l","L1 / LB",False,False),
 ("input_r","R1 / RB",False,False),
 ("input_l2","L2 / LT",False,True),
 ("input_r2","R2 / RT",False,True),
 ("input_l3","pressione o analógico esquerdo",False,False),
 ("input_r3","pressione o analógico direito",False,False),
 ("input_up","D-Pad para CIMA",True,True),
 ("input_down","D-Pad para BAIXO",True,True),
 ("input_left","D-Pad para ESQUERDA",True,True),
 ("input_right","D-Pad para DIREITA",True,True),
 ("input_l_x_minus","analógico esquerdo para ESQUERDA",False,True),
 ("input_l_x_plus","analógico esquerdo para DIREITA",False,True),
 ("input_l_y_minus","analógico esquerdo para CIMA",False,True),
 ("input_l_y_plus","analógico esquerdo para BAIXO",False,True),
 ("input_r_x_minus","analógico direito para ESQUERDA",False,True),
 ("input_r_x_plus","analógico direito para DIREITA",False,True),
 ("input_r_y_minus","analógico direito para CIMA",False,True),
 ("input_r_y_plus","analógico direito para BAIXO",False,True),
]

lines=[
 'input_driver = "udev"',
 f'input_device = "{j.get_name()}"',
 f'input_device_display_name = "{j.get_name()} (JottaBox)"',
]

mapped=[]
for key,label,hat,axis in steps:
    kind,val=capture(j,label,allow_hat=hat,allow_axis=axis)
    if kind=="CANCEL":
        pygame.quit(); sys.exit(0)
    if kind=="SKIP":
        continue
    ln=cfg_line(key,kind,val)
    if ln:
        lines.append(ln)
        mapped.append((key,kind,val))

# Keep menu toggle on Guide/Home only if user explicitly maps it later.
safe_name="".join(c if c not in '/\\\0' else "_" for c in j.get_name()).strip() or "JottaBox Controller"
out=os.path.join(AUTO,safe_name+".cfg")
with open(out,"w") as f:
    f.write("\n".join(lines)+"\n")

# Ensure Flatpak RetroArch uses writable autoconfig dir and autodetection.
os.makedirs(RA_DIR,exist_ok=True)
cfg={}
raw=[]
if os.path.exists(CFG):
    with open(CFG,errors="ignore") as f:
        raw=f.readlines()

wanted={
    "joypad_autoconfig_dir": os.path.join(RA_DIR,"autoconfig"),
    "input_autodetect_enable":"true",
    "input_joypad_driver":"udev",
    "input_player1_joypad_index":"0",
}
seen=set()
new=[]
for line in raw:
    m=None
    if "=" in line and not line.lstrip().startswith("#"):
        k=line.split("=",1)[0].strip()
        if k in wanted:
            v=wanted[k]
            if v in ("true","false") or v.isdigit():
                new.append(f'{k} = "{v}"\n')
            else:
                new.append(f'{k} = "{v}"\n')
            seen.add(k)
            continue
    new.append(line)
for k,v in wanted.items():
    if k not in seen:
        new.append(f'{k} = "{v}"\n')
with open(CFG,"w") as f:
    f.writelines(new)

with open(LOG,"a") as f:
    f.write("\n===== PERFIL SALVO =====\n")
    f.write(out+"\n")
    for x in lines:f.write(x+"\n")

message("Controle configurado","Perfil salvo com sucesso",GREEN,"ENTER testar   ESC sair")
test=wait_enter()
if test:
    # Visual test screen
    while True:
        header("Testar controle",j.get_name())
        center(txt("Pressione botões e mova os analógicos",F2,WHITE),int(H*.32))
        yy=int(H*.42)
        vals=[]
        for b in range(j.get_numbuttons()):
            try:
                if j.get_button(b): vals.append(f"B{b}")
            except: pass
        for h in range(j.get_numhats()):
            try:
                v=j.get_hat(h)
                if v!=(0,0): vals.append(f"H{h}:{v}")
            except: pass
        for a in range(j.get_numaxes()):
            try:
                v=j.get_axis(a)
                if abs(v)>.25: vals.append(f"A{a}:{v:+.2f}")
            except: pass
        center(txt("   ".join(vals) if vals else "Aguardando entrada...",F2,CYAN if vals else MUTED),yy)
        center(txt("ESC / B = sair",F4,MUTED),int(H*.88))
        pygame.display.flip()
        leave=False
        for e in pygame.event.get():
            if e.type==pygame.KEYDOWN and e.key==pygame.K_ESCAPE: leave=True
            if e.type==pygame.JOYBUTTONDOWN and e.button==1: leave=True
        if leave: break
        clock.tick(60)

pygame.quit()
PYEOF
  chmod +x "$CFG_DIR/controller_wizard.py"

  cat > "$BIN_DIR/jottabox-configure-controller" <<EOF
#!/usr/bin/env bash
exec /usr/bin/python3 "$CFG_DIR/controller_wizard.py"
EOF
  chmod +x "$BIN_DIR/jottabox-configure-controller"

  cat > "$BIN_DIR/jottabox-test-controller" <<EOF
#!/usr/bin/env bash
exec /usr/bin/python3 "$CFG_DIR/controller_wizard.py"
EOF
  chmod +x "$BIN_DIR/jottabox-test-controller"
}

