create_launcher() {
  say "Criando interface visual JottaBox v9"

  # Remove inicializadores legados que abriam M720Q/XCloud sozinhos.
  rm -f "$AUTOSTART_DIR/m720q-console.desktop"         "$AUTOSTART_DIR/xbox-console.desktop"         "$AUTOSTART_DIR/xbox-cloud.desktop" 2>/dev/null || true

  cat > "$CFG_DIR/launcher.py" <<'PYEOF'
