        screen.blit(pygame.transform.smoothscale(wall,(W,H)),(0,0))
    else:
        screen.fill((2,10,25))
    shade=pygame.Surface((W,H),pygame.SRCALPHA); shade.fill((0,6,18,48)); screen.blit(shade,(0,0))

def header():
    update_status()
    m=int(W*.06)
    a=txt("Jotta",F_LOGO,WHITE); b=txt("Box",F_LOGO,CYAN)
    screen.blit(a,(m,int(H*.034))); screen.blit(b,(m+a.get_width()-3,int(H*.034)))
    screen.blit(txt("MAIS JOGOS.  MAIS MOMENTOS.",F_TAG,(131,191,230)),(m+3,int(H*.108)))

    now=txt(time.strftime("%H:%M"),F_TITLE,WHITE)
    date=txt(time.strftime("%d/%m/%Y"),F_SMALL,WHITE)
    screen.blit(now,(W-m-now.get_width(),int(H*.036)))
    screen.blit(date,(W-m-date.get_width(),int(H*.079)))

    y=int(H*.118); x=int(W*.38)
    vals=[
      ("●  Controle conectado" if joysticks else "●  Controle desconectado",GREEN if joysticks else AMBER),
      ("●  Internet" if status.get("net") else "●  Sem internet",GREEN if status.get("net") else AMBER),
      (status.get("disk","-- GB livres"),WHITE),
    ]
    for label,c in vals:
        s=txt(label,F_STATUS,c); screen.blit(s,(x,y)); x+=s.get_width()+int(W*.035)

def alpha_rect(rect,color,radius=22,width=0):
    surf=pygame.Surface((rect.w,rect.h),pygame.SRCALPHA)
    pygame.draw.rect(surf,color,surf.get_rect(),width=width,border_radius=radius)
    screen.blit(surf,rect.topleft)

def glow(rect):
    for n,a in ((18,20),(10,42),(5,90)):
        rr=rect.inflate(n,n)
        s=pygame.Surface((rr.w,rr.h),pygame.SRCALPHA)
        pygame.draw.rect(s,(*CYAN,a),s.get_rect(),3,border_radius=26)
        screen.blit(s,rr.topleft)

def draw_art(art,rect):
    if not art:
        alpha_rect(rect,(8,22,48,235),22)
        return
    img=pygame.transform.smoothscale(art,(rect.w,rect.h))
    # rounded mask
    mask=pygame.Surface((rect.w,rect.h),pygame.SRCALPHA)
    pygame.draw.rect(mask,(255,255,255,255),mask.get_rect(),border_radius=22)
    img.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MIN)
    screen.blit(img,rect.topleft)

def draw_home():
    margin=int(W*.085); top=int(H*.198); gap=int(W*.016)
    cw=int((W-2*margin-2*gap)/3); ch=int(H*.252); rg=int(H*.022)
    for i,(kind,cmd) in enumerate(MAIN):
        row,col=divmod(i,3)
        r=pygame.Rect(margin+col*(cw+gap),top+row*(ch+rg),cw,ch)
        if i==selected: glow(r)
        draw_art(HOME_ART.get(kind),r)
        pygame.draw.rect(screen,CYAN if i==selected else (65,98,137),r,3 if i==selected else 1,border_radius=22)

def section_title(title):
    x=int(W*.074); y=int(H*.225)
    pygame.draw.line(screen,CYAN,(x,y-20),(x,y+62),3)
    screen.blit(txt(title,F_BODY,(165,205,236)),(x+22,y))
    pygame.draw.line(screen,CYAN,(x+22,y+38),(x+50,y+38),3)

def draw_native_card(kind,r,is_selected):
    label,sub,icon=MENU_META.get(kind,(kind.upper(),"","•"))

    if is_selected:
        glow(r)

    panel=pygame.Surface((r.w,r.h),pygame.SRCALPHA)
    panel.fill((4,23,52,218 if is_selected else 190))
    screen.blit(panel,r.topleft)

    pygame.draw.rect(
        screen,
        CYAN if is_selected else (62,101,145),
        r,
        3 if is_selected else 1,
        border_radius=max(12,int(r.h*.16))
    )

    icon_r=max(20,int(r.h*.27))
    icon_c=(r.x+int(r.h*.58),r.centery)
    pygame.draw.circle(screen,(22,91,147),icon_c,icon_r)
    pygame.draw.circle(screen,CYAN if is_selected else (108,181,225),icon_c,icon_r,2)

    it=txt(icon,F_BODY,WHITE)
    screen.blit(it,(icon_c[0]-it.get_width()//2,icon_c[1]-it.get_height()//2))

    tx=r.x+int(r.h*1.15)
    title_font=F_BODY if r.h < int(H*.105) else F_TITLE
    screen.blit(txt(label,title_font,WHITE),(tx,r.y+int(r.h*.17)))
    screen.blit(txt(sub,F_SMALL,(100,202,247)),(tx,r.y+int(r.h*.57)))

    ar=txt("›",F_TITLE,CYAN if is_selected else WHITE)
    screen.blit(ar,(r.right-ar.get_width()-22,r.centery-ar.get_height()//2))

def draw_list(title,items,arts):
    section_title(title)
    left=int(W*.225); top=int(H*.202); width=int(W*.64)

    if len(items)>=7:
        rh=int(H*.083); gap=int(H*.007)
    elif len(items)>4:
        rh=int(H*.108); gap=int(H*.010)
    else:
        rh=int(H*.137); gap=int(H*.015)

    for i,(kind,cmd) in enumerate(items):
        r=pygame.Rect(left,top+i*(rh+gap),width,rh)

        if page in ("settings","tools","power"):
            draw_native_card(kind,r,i==selected)
        else:
            if i==selected:
                glow(r)
            draw_art(arts.get(kind),r)
            pygame.draw.rect(
                screen,
                CYAN if i==selected else (61,91,128),
                r,
                3 if i==selected else 1,
                border_radius=22
            )

def footer():
    s=txt("A  Selecionar     B  Voltar     SELECT + START  Sair do jogo",F_SMALL,MUTED)
    screen.blit(s,((W-s.get_width())//2,H-int(H*.048)))

def active():
    return {"home":MAIN,"library":LIBRARY,"settings":SETTINGS,"tools":TOOLS,"power":POWER}[page]


def virtual_keyboard(initial=""):
    value=initial
    rows=[
        list("1234567890"),
        list("QWERTYUIOP"),
        list("ASDFGHJKL"),
        list("ZXCVBNM.-_"),
        [":","/","@","?","&","=","SPACE","BKSP"],
        ["CLEAR","OK","CANCEL"],
    ]
    rr=cc=0

    def clamp():
        nonlocal cc
        cc=max(0,min(cc,len(rows[rr])-1))

    while True:
        background(); header(); section_title("TECLADO VIRTUAL")

        field=pygame.Rect(int(W*.12),int(H*.19),int(W*.76),int(H*.09))
        fs=pygame.Surface((field.w,field.h),pygame.SRCALPHA)
        fs.fill((0,10,25,235)); screen.blit(fs,field.topleft)
        pygame.draw.rect(screen,CYAN,field,2,border_radius=14)
        shown=value[-90:] if value else "Digite..."
        screen.blit(txt(shown,F_BODY,WHITE if value else MUTED),(field.x+20,field.y+20))

        top=int(H*.33); row_h=int(H*.083)
        for r,row in enumerate(rows):
            gap=8
            usable=int(W*.76)
            kw=max(58,int((usable-gap*(len(row)-1))/len(row)))
            x0=(W-(kw*len(row)+gap*(len(row)-1)))//2
            for c,key in enumerate(row):
                kr=pygame.Rect(x0+c*(kw+gap),top+r*row_h,kw,row_h-10)
                sel=(r==rr and c==cc)
                ps=pygame.Surface((kr.w,kr.h),pygame.SRCALPHA)
                ps.fill((9,49,88,245) if sel else (4,25,51,225))
                screen.blit(ps,kr.topleft)
                pygame.draw.rect(screen,CYAN if sel else (60,105,150),kr,2 if sel else 1,border_radius=12)
                label="⌫" if key=="BKSP" else ("ESPAÇO" if key=="SPACE" else key)
                kt=txt(label,F_SMALL if len(label)>4 else F_BODY,WHITE)
                screen.blit(kt,(kr.centerx-kt.get_width()//2,kr.centery-kt.get_height()//2))

        hint=txt("D-pad mover  •  A selecionar  •  B cancelar",F_SMALL,MUTED)
        screen.blit(hint,(W//2-hint.get_width()//2,int(H*.91)))
        pygame.display.flip()

        for e in pygame.event.get():
            if e.type==pygame.KEYDOWN:
                if e.key==pygame.K_ESCAPE:
                    return None
                if e.key==pygame.K_UP: rr=(rr-1)%len(rows); clamp(); continue
                if e.key==pygame.K_DOWN: rr=(rr+1)%len(rows); clamp(); continue
                if e.key==pygame.K_LEFT: cc=(cc-1)%len(rows[rr]); continue
                if e.key==pygame.K_RIGHT: cc=(cc+1)%len(rows[rr]); continue
                if e.key==pygame.K_BACKSPACE: value=value[:-1]; continue
                if e.key==pygame.K_RETURN:
                    key=rows[rr][cc]
                elif e.unicode and e.unicode.isprintable():
                    value+=e.unicode
                    continue
                else:
                    continue
            elif e.type==pygame.JOYHATMOTION:
                x,y=e.value
                if y>0: rr=(rr-1)%len(rows); clamp()
                elif y<0: rr=(rr+1)%len(rows); clamp()
                elif x<0: cc=(cc-1)%len(rows[rr])
                elif x>0: cc=(cc+1)%len(rows[rr])
                continue
            elif e.type==pygame.JOYBUTTONDOWN:
                if e.button==1:
                    return None
                if e.button!=0:
                    continue
                key=rows[rr][cc]
            else:
                continue

            if key=="OK": return value
            if key=="CANCEL": return None
            if key=="CLEAR": value=""
            elif key=="BKSP": value=value[:-1]
            elif key=="SPACE": value+=" "
            else: value+=key

        clock.tick(60)

def controller_wizard_native():
    pygame.joystick.quit()
    pygame.joystick.init()

    joys=[]
    for i in range(pygame.joystick.get_count()):
        try:
            j=pygame.joystick.Joystick(i); j.init(); joys.append(j)
        except Exception:
            pass

    if not joys:
        while True:
            background(); header(); section_title("CONFIGURAR CONTROLE")
            msg=txt("Nenhum controle encontrado",F_TITLE,WHITE)
            sub=txt("Conecte o controle e pressione A/ENTER para tentar novamente",F_BODY,MUTED)
            screen.blit(msg,(W//2-msg.get_width()//2,int(H*.42)))
            screen.blit(sub,(W//2-sub.get_width()//2,int(H*.49)))
            pygame.display.flip()
            for e in pygame.event.get():
                if e.type==pygame.KEYDOWN and e.key==pygame.K_ESCAPE: return
                if e.type==pygame.JOYBUTTONDOWN and e.button==1: return
                if (e.type==pygame.KEYDOWN and e.key==pygame.K_RETURN) or (e.type==pygame.JOYBUTTONDOWN and e.button==0):
                    return controller_wizard_native()
            clock.tick(30)

    j=joys[0]
    steps=[
        ("input_b_btn","BOTÃO INFERIOR / A / X"),
        ("input_a_btn","BOTÃO DIREITO / B / CÍRCULO"),
        ("input_y_btn","BOTÃO ESQUERDO / X / QUADRADO"),
        ("input_x_btn","BOTÃO SUPERIOR / Y / TRIÂNGULO"),
        ("input_select_btn","SELECT / SHARE / BACK"),
        ("input_start_btn","START / OPTIONS / MENU"),
        ("input_l_btn","L1 / LB"),
        ("input_r_btn","R1 / RB"),
    ]
    mapping={}

    pygame.event.clear()
    for key,label in steps:
        captured=None
        while captured is None:
            background(); header(); section_title("CONFIGURAR CONTROLE")
            t=txt(label,F_TITLE,WHITE)
            s=txt("Pressione o botão correspondente",F_BODY,CYAN)
            esc=txt("B/ESC para cancelar",F_SMALL,MUTED)
            screen.blit(t,(W//2-t.get_width()//2,int(H*.40)))
            screen.blit(s,(W//2-s.get_width()//2,int(H*.48)))
            screen.blit(esc,(W//2-esc.get_width()//2,int(H*.80)))
            pygame.display.flip()

            for e in pygame.event.get():
                if e.type==pygame.KEYDOWN and e.key==pygame.K_ESCAPE:
                    return
                if e.type==pygame.JOYBUTTONDOWN:
                    if e.button==1 and label.startswith("BOTÃO") is False:
                        # B can be a legitimate mapping, only cancel later stages via ESC
                        pass
                    captured=e.button
                    break
            clock.tick(60)
        mapping[key]=captured
        time.sleep(.12)
        pygame.event.clear()

    # D-pad
    hatmap={}
    for name,want in [("up",(0,1)),("down",(0,-1)),("left",(-1,0)),("right",(1,0))]:
        done=False
        while not done:
            background(); header(); section_title("CONFIGURAR CONTROLE")
            t=txt("D-PAD "+name.upper(),F_TITLE,WHITE)
            screen.blit(t,(W//2-t.get_width()//2,int(H*.43)))
            screen.blit(txt("Pressione a direção",F_BODY,CYAN),(int(W*.40),int(H*.51)))
            pygame.display.flip()
            for e in pygame.event.get():
                if e.type==pygame.KEYDOWN and e.key==pygame.K_ESCAPE: return
                if e.type==pygame.JOYHATMOTION and e.value==want:
                    hatmap[name]=f"h0{name}"
                    done=True
                    break
            clock.tick(60)

    cfgdir=os.path.expanduser("~/.var/app/org.libretro.RetroArch/config/retroarch/autoconfig/udev")
    os.makedirs(cfgdir,exist_ok=True)
    safe="".join(c if c.isalnum() or c in " ._-" else "_" for c in j.get_name()).strip() or "JottaBox Controller"
    cfg=os.path.join(cfgdir,safe+".cfg")
    with open(cfg,"w",encoding="utf-8") as f:
        f.write('input_driver = "udev"\n')
        f.write(f'input_device = "{j.get_name()}"\n')
        f.write(f'input_device_display_name = "{j.get_name()} (JottaBox)"\n')
        for k,v in mapping.items():
            f.write(f'{k} = "{v}"\n')
        for name,val in hatmap.items():
            f.write(f'input_{name}_btn = "{val}"\n')

    retro=os.path.expanduser("~/.var/app/org.libretro.RetroArch/config/retroarch/retroarch.cfg")
    os.makedirs(os.path.dirname(retro),exist_ok=True)
    lines=[]
    if os.path.exists(retro):
        lines=open(retro,encoding="utf-8",errors="ignore").read().splitlines()
    wanted={
      "joypad_autoconfig_dir":os.path.expanduser("~/.var/app/org.libretro.RetroArch/config/retroarch/autoconfig"),
      "input_autodetect_enable":"true",
      "input_joypad_driver":"udev",
      "input_player1_joypad_index":"0",
    }
    out=[]
    seen=set()
    for line in lines:
        k=line.split("=",1)[0].strip() if "=" in line else ""
        if k in wanted:
            out.append(f'{k} = "{wanted[k]}"'); seen.add(k)
        else:
            out.append(line)
    for k,v in wanted.items():
        if k not in seen: out.append(f'{k} = "{v}"')
    open(retro,"w",encoding="utf-8").write("\n".join(out)+"\n")

    while True:
        background(); header(); section_title("CONFIGURAR CONTROLE")
        a=txt("Controle configurado com sucesso",F_TITLE,WHITE)
        b=txt(j.get_name(),F_BODY,CYAN)
        c=txt("A / ENTER / B / ESC para voltar",F_SMALL,MUTED)
        screen.blit(a,(W//2-a.get_width()//2,int(H*.42)))
        screen.blit(b,(W//2-b.get_width()//2,int(H*.50)))
        screen.blit(c,(W//2-c.get_width()//2,int(H*.72)))
        pygame.display.flip()
        for e in pygame.event.get():
            if e.type==pygame.KEYDOWN and e.key in (pygame.K_RETURN,pygame.K_ESCAPE): return
            if e.type==pygame.JOYBUTTONDOWN and e.button in (0,1): return
        clock.tick(30)

ANSI_RE=re.compile(r"\x1b\[[0-?]*[ -/]*[@-~]")

def _clean_term(s):
    s=ANSI_RE.sub("",s)
    s=s.replace("\r\n","\n").replace("\r","\n")
    return "".join(ch for ch in s if ch in "\n\t" or ord(ch)>=32)

def embedded_terminal(cmd,title="JottaBox"):
    master,slave=pty.openpty()
    env=os.environ.copy()
    env["TERM"]="xterm-256color"
    env["COLUMNS"]="108"
    env["LINES"]="28"

    proc=subprocess.Popen(
        ["bash","-lc",cmd],
        stdin=slave,
        stdout=slave,
        stderr=slave,
        env=env,
        start_new_session=True,
        close_fds=True
    )
    os.close(slave)
    os.set_blocking(master,False)

    lines=deque(maxlen=30)
    partial=""
    finished=False

    def feed(data):
        nonlocal partial
        partial += _clean_term(data)
        parts=partial.split("\n")
        partial=parts.pop() if parts else ""
        for line in parts:
            lines.append(line[-150:])

    def send(data):
        try:
            os.write(master,data)
        except Exception:
            pass

    while True:
        try:
            while True:
                ready,_,_=select.select([master],[],[],0)
                if not ready:
                    break
                chunk=os.read(master,8192)
                if not chunk:
                    break
                feed(chunk.decode("utf-8","replace"))
        except (BlockingIOError,OSError):
            pass

        rc=proc.poll()
        if rc is not None and not finished:
            finished=True
            if partial:
                lines.append(partial[-150:])
                partial=""
            lines.append("")
            lines.append("Concluído." if rc==0 else f"Processo encerrado (código {rc}).")
            lines.append("A / ENTER / B / ESC para voltar ao JottaBox")

        background()
        header()
        section_title(title.upper())

        box=pygame.Rect(int(W*.12),int(H*.18),int(W*.76),int(H*.69))
        surf=pygame.Surface((box.w,box.h),pygame.SRCALPHA)
        surf.fill((0,8,20,240))
        screen.blit(surf,box.topleft)
        pygame.draw.rect(screen,CYAN,box,2,border_radius=18)

        head=pygame.Rect(box.x,box.y,box.w,int(H*.065))
        pygame.draw.rect(screen,(7,35,67),head,border_radius=18)
        pygame.draw.rect(screen,(7,35,67),(head.x,head.bottom-18,head.w,18))
        screen.blit(txt("JottaBox • Console interno",F_BODY,WHITE),(head.x+22,head.y+16))

        font_term=font(max(13,int(H*.017)))
        lh=max(20,int(H*.026))
        y=head.bottom+18

        visible=list(lines)
        if partial:
            visible.append(partial[-150:])

        max_rows=max(1,int((box.bottom-y-38)/lh))
        visible=visible[-max_rows:]

        for ln in visible:
            color=(210,231,245)
            up=ln.upper()
            if "ERRO" in up or "ERROR" in up:
                color=(255,115,115)
            elif ln.startswith("OK:") or "Concluído." in ln:
                color=(104,238,164)
            screen.blit(txt(ln,font_term,color),(box.x+22,y))
            y+=lh

        hint=("Teclado físico disponível • A = ENTER • B = interromper"
              if not finished else
              "A / ENTER / B / ESC = voltar")
        hs=txt(hint,F_SMALL,MUTED)
        screen.blit(hs,(box.x+22,box.bottom-hs.get_height()-14))

        pygame.display.flip()

        for e in pygame.event.get():
            if e.type==pygame.QUIT:
                if not finished:
                    try:
                        os.killpg(proc.pid,signal.SIGTERM)
                    except Exception:
                        pass
                try:
                    os.close(master)
                except Exception:
                    pass
                return

            if e.type==pygame.KEYDOWN:
                if finished and e.key in (pygame.K_RETURN,pygame.K_ESCAPE):
                    try:
                        os.close(master)
                    except Exception:
                        pass
                    pygame.event.clear()
                    return

                if not finished:
                    if e.key==pygame.K_RETURN:
                        send(b"\n")
                    elif e.key==pygame.K_BACKSPACE:
                        send(b"\x7f")
                    elif e.key==pygame.K_UP:
                        send(b"\x1b[A")
                    elif e.key==pygame.K_DOWN:
                        send(b"\x1b[B")
                    elif e.key==pygame.K_RIGHT:
                        send(b"\x1b[C")
                    elif e.key==pygame.K_LEFT:
                        send(b"\x1b[D")
                    elif e.key==pygame.K_ESCAPE:
                        send(b"\x03")
                    elif e.unicode and e.unicode.isprintable():
                        send(e.unicode.encode("utf-8"))

            elif e.type==pygame.JOYBUTTONDOWN:
                if finished and e.button in (0,1):
                    try:
                        os.close(master)
                    except Exception:
                        pass
                    pygame.event.clear()
                    return

                if not finished:
                    if e.button==0:
                        send(b"\n")
                    elif e.button==1:
                        send(b"\x03")

            elif e.type==pygame.JOYHATMOTION and not finished:
                x,yh=e.value
                if yh>0:
                    send(b"\x1b[A")
                elif yh<0:
                    send(b"\x1b[B")
                elif x>0:
                    send(b"\x1b[C")
                elif x<0:
                    send(b"\x1b[D")

        clock.tick(30)

def launch(cmd):
    global page,selected
    if cmd=="__library__": page,selected="library",0; return
    if cmd=="__settings__": page,selected="settings",0; return
    if cmd=="__tools__": page,selected="tools",0; return
    if cmd=="__power__": page,selected="power",0; return
    if cmd=="__keyboard__":
        virtual_keyboard("")
        pygame.event.clear()
        return
    if cmd=="__controller_native__":
        controller_wizard_native()
        pygame.event.clear()
        return
    if cmd=="__back__":
        if page=="tools":
            page,selected="settings",0
        else:
            page,selected="home",0
        return
    if cmd=="__shutdown__": subprocess.run(["systemctl","poweroff"]); return
    if cmd=="__reboot__": subprocess.run(["systemctl","reboot"]); return
    if cmd=="__desktop__":
        pygame.quit()
        raise SystemExit(0)

    admin=any(cmd.endswith(x) for x in (
      "jottabox-import-roms","jottabox-clean-roms","jottabox-update",
      "jottabox-status","jottabox-repair-hotkey","jottabox-storage",
      "jottabox-controller-diagnostics"))

    if admin:
        titles={
          "jottabox-import-roms":"Importar jogos",
          "jottabox-clean-roms":"Organizar biblioteca",
          "jottabox-update":"Atualizar JottaBox",
          "jottabox-status":"Status do sistema",
          "jottabox-repair-hotkey":"Reparar hotkey",
          "jottabox-storage":"Armazenamento",
          "jottabox-controller-diagnostics":"Diagnóstico do controle",
        }
        name=os.path.basename(cmd)
        embedded_terminal(cmd,titles.get(name,"JottaBox"))
        pygame.mouse.set_visible(False)
        pygame.event.clear()
        return

    run=cmd
    pygame.display.iconify()
    pygame.mouse.set_visible(True)

    try:
        if cmd.endswith("xbox-cloud"):
            # Chromium/Edge pode retornar do comando inicial antes da janela fechar.
            # Inicia o XCloud e mantém o JottaBox escondido enquanto existir
            # qualquer processo usando o perfil exclusivo jottabox-edge-xcloud.
            subprocess.Popen(run, shell=True)

            # Dá tempo para o Edge criar o processo real.
            time.sleep(1.5)

            deadline=time.monotonic()+15
            seen_edge=False

            while True:
                edge_alive = subprocess.run(
                    ["pgrep","-f","jottabox-edge-xcloud"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL
                ).returncode == 0

                if edge_alive:
                    seen_edge=True
                elif seen_edge:
                    break
                elif time.monotonic() > deadline:
                    break

                pygame.event.pump()
                time.sleep(.35)

        else:
            subprocess.run(run,shell=True)

    except Exception:
        pass

    pygame.mouse.set_visible(False)
    pygame.display.set_mode((W,H),pygame.FULLSCREEN|pygame.DOUBLEBUF)

def move(d):
    global selected
    selected=(selected+d)%len(active())

def back():
    global page,selected
    if page=="home":
        page,selected="power",0
    elif page=="tools":
        page,selected="settings",0
    else:
        page,selected="home",0

def draw():
    background(); header()
    if page=="home": draw_home()
    elif page=="library": draw_list("BIBLIOTECA",LIBRARY,LIB_ART)
    elif page=="settings": draw_list("CONFIGURAÇÕES",SETTINGS,SET_ART)
    elif page=="tools": draw_list("FERRAMENTAS",TOOLS,SET_ART)
    elif page=="power": draw_list("ENERGIA",POWER,POWER_ART)
    footer(); pygame.display.flip()

if splash:
    screen.blit(pygame.transform.smoothscale(splash,(W,H)),(0,0)); pygame.display.flip()
    t=time.monotonic()
    while time.monotonic()-t<2.1:
        pygame.event.pump(); clock.tick(60)

running=True
while running:
    now=time.monotonic()
    for e in pygame.event.get():
        if e.type==pygame.QUIT: running=False
        elif e.type in (pygame.JOYDEVICEADDED,pygame.JOYDEVICEREMOVED): refresh_joy()
        elif e.type==pygame.KEYDOWN:
            if e.key in (pygame.K_LEFT,pygame.K_UP,pygame.K_a,pygame.K_w): move(-1)
            elif e.key in (pygame.K_RIGHT,pygame.K_DOWN,pygame.K_d,pygame.K_s): move(1)
            elif e.key in (pygame.K_RETURN,pygame.K_SPACE): launch(active()[selected][1])
            elif e.key in (pygame.K_ESCAPE,pygame.K_BACKSPACE): back()
        elif e.type==pygame.JOYBUTTONDOWN:
            # SELECT + Y abre o teclado virtual dentro do JottaBox.
            try:
                if e.button==3 and any(j.get_numbuttons()>6 and (j.get_button(6) or (j.get_numbuttons()>8 and j.get_button(8))) for j in joysticks):
                    virtual_keyboard("")
                    pygame.event.clear()
                    continue
            except Exception:
                pass
            if e.button==0: launch(active()[selected][1])
            elif e.button==1: back()
        elif e.type==pygame.JOYHATMOTION:
            if e.value[0]<0 or e.value[1]>0: move(-1)
            elif e.value[0]>0 or e.value[1]<0: move(1)

    if joysticks and now-last_nav>.23:
        try:
            x=joysticks[0].get_axis(0); y=joysticks[0].get_axis(1)
            if x<-.72 or y<-.72: move(-1); last_nav=now
            elif x>.72 or y>.72: move(1); last_nav=now
        except Exception: pass
    draw(); clock.tick(60)

pygame.quit()
PYEOF

  chmod +x "$CFG_DIR/launcher.py"

  cat > "$BIN_DIR/jottabox-console" <<EOF
#!/usr/bin/env bash
xset s off >/dev/null 2>&1 || true
xset -dpms >/dev/null 2>&1 || true
xset s noblank >/dev/null 2>&1 || true
exec /usr/bin/python3 "$CFG_DIR/launcher.py"
EOF
  chmod +x "$BIN_DIR/jottabox-console"
  ln -sf "$BIN_DIR/jottabox-console" "$BIN_DIR/jottabox"

  cat > "$AUTOSTART_DIR/jottabox-console.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=JottaBox
Comment=JottaBox Game Console
Exec=$BIN_DIR/jottabox-console
Terminal=false
X-GNOME-Autostart-enabled=true
Hidden=false
EOF

  cat > "$DESKTOP_DIR/jottabox-console.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=JottaBox
Comment=JottaBox Game Console
Exec=$BIN_DIR/jottabox-console
Terminal=false
Categories=Game;
EOF

  cat > "$DESKTOP_DIR/jottabox-return.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=Voltar ao JottaBox
Comment=Abrir a interface JottaBox
Exec=$BIN_DIR/jottabox-console
Terminal=false
Categories=Game;
EOF
}

configure_console_mode() {
  say "Configurando Linux Mint em modo console"

  gsettings set org.cinnamon.desktop.session idle-delay 0 2>/dev/null || true
  gsettings set org.cinnamon.desktop.screensaver lock-enabled false 2>/dev/null || true
  gsettings set org.cinnamon.desktop.screensaver lock-delay 0 2>/dev/null || true
  gsettings set org.cinnamon.settings-daemon.plugins.power sleep-inactive-ac-timeout 0 2>/dev/null || true
  gsettings set org.cinnamon.settings-daemon.plugins.power idle-dim false 2>/dev/null || true

  if command -v powerprofilesctl >/dev/null 2>&1; then
    powerprofilesctl set performance 2>/dev/null || true
  fi

  local dm=""
  if [[ -r /etc/X11/default-display-manager ]]; then
    dm="$(basename "$(cat /etc/X11/default-display-manager 2>/dev/null)")"
  fi

  if [[ "$dm" == "lightdm" ]] || systemctl is-active --quiet lightdm 2>/dev/null; then
    sudo groupadd -f nopasswdlogin
    sudo usermod -aG nopasswdlogin "$REAL_USER"
    sudo mkdir -p /etc/lightdm/lightdm.conf.d
    cat <<EOF | sudo tee /etc/lightdm/lightdm.conf.d/90-jottabox-autologin.conf >/dev/null
[Seat:*]
autologin-user=$REAL_USER
autologin-user-timeout=0
user-session=cinnamon
EOF
    ok "Login automático configurado no LightDM para $REAL_USER"

    # Evita que o Cinnamon restaure Edge/Steam/outros apps da sessão anterior.
    if command -v gsettings >/dev/null 2>&1; then
      if gsettings list-keys org.cinnamon.SessionManager 2>/dev/null | grep -qx 'auto-save-session'; then
        gsettings set org.cinnamon.SessionManager auto-save-session false 2>/dev/null || true
      fi
    fi
    rm -rf "$HOME_DIR/.cache/sessions/"* 2>/dev/null || true
  else
    warn "LightDM não detectado; autologin não foi alterado."
  fi
}

import_roms() {
  ensure_dirs
  local src="${1:-$HOME_DIR/Downloads/rom}"
  [[ -d "$src" ]] || die "Pasta não encontrada: $src"

  say "Importando e organizando ROMs de $src"
  echo "Modo seguro: COPIA/EXTRAI para ~/ROMs e preserva a origem."
  echo "Downloads incompletos permanecem em $src."

  python3 - "$src" "$ROM_ROOT" <<'PYEOF'
import os, re, sys, shlex, shutil, zipfile, subprocess, tempfile
from pathlib import Path

SRC = Path(sys.argv[1]).expanduser().resolve()
ROOT = Path(sys.argv[2]).expanduser().resolve()

EXT_SYSTEM = {
    ".nes":"nes",
    ".sfc":"snes", ".smc":"snes",
    ".gb":"gb", ".gbc":"gbc", ".gba":"gba",
    ".nds":"nds",
    ".n64":"n64", ".z64":"n64", ".v64":"n64",
    ".md":"megadrive", ".gen":"megadrive", ".smd":"megadrive",
    ".32x":"sega32x",
    ".sms":"mastersystem", ".gg":"gamegear",
    ".pce":"pcengine",
    ".a26":"atari2600", ".a52":"atari5200", ".a78":"atari7800",
    ".lnx":"atarilynx",
    ".ngp":"ngp", ".ngc":"ngpc",
    ".ws":"wonderswan", ".wsc":"wonderswancolor",
    ".pbp":"psx", ".cso":"psp",
    ".cdi":"dreamcast",
    ".rvz":"gc", ".gcm":"gc", ".gcz":"gc",
    ".wbfs":"wii",
}

# Nome/caminho de pacotes de coleção.
NAME_HINTS = [
    (("master system","mastersystem"), "mastersystem"),
    (("super nintendo","snes"), "snes"),
    (("nintendo - nes"," nintendo nes","/nes"), "nes"),
    (("nintendo - ds","nintendo ds"," nds","/nds"), "nds"),
    (("game boy advance"," gba"), "gba"),
    (("game boy color"," gbc"), "gbc"),
    (("game boy"," gb"), "gb"),
    (("mega drive","megadrive","genesis"), "megadrive"),
    (("sega 32x","32x"), "sega32x"),
    (("game gear","gamegear"), "gamegear"),
    (("atari - 2600","atari 2600"), "atari2600"),
    (("atari - 5200","atari 5200"), "atari5200"),
    (("atari - 7800","atari 7800"), "atari7800"),
    (("mame 2003","mame2003","arcade"), "arcade"),
    (("neo geo","neogeo"), "neogeo"),
    (("turbografx-16","turbografx 16","pc engine"), "pcengine"),
    (("dreamcast",), "dreamcast"),
    (("saturn",), "saturn"),
    (("sega cd","mega cd","megacd","segacd"), "segacd"),
    (("ps1","psx","playstation 1","sony - ps1"), "psx"),
    (("ps2","playstation 2","sony - ps2"), "ps2"),
    (("psp","sony - psp"), "psp"),
    (("gamecube","game cube"), "gc"),
    (("wii-u","wii u","wiiu"), "_revisar"),
    (("wii",), "wii"),
    (("3ds",), "_revisar"),
]

DISC_HINTS = [
    (("dreamcast",), "dreamcast"),
    (("saturn",), "saturn"),
    (("segacd","sega cd","mega cd","megacd"), "segacd"),
    (("pcenginecd","pc engine cd","turbografx cd","tg-cd"), "pcenginecd"),
    (("ps1","psx","playstation 1","sony - ps1"), "psx"),
    (("ps2","playstation 2","sony - ps2"), "ps2"),
    (("psp",), "psp"),
    (("gamecube","game cube"), "gc"),
    (("wii",), "wii"),
]

for d in set(EXT_SYSTEM.values()) | {
    "segacd","saturn","pcenginecd","ps2","gc","wii","dreamcast",
    "neogeo","arcade","_revisar"
}:
    (ROOT/d).mkdir(parents=True, exist_ok=True)

handled=set()
copied=exists=review=expanded=broken=0
broken_files=[]

def hint_text(p):
    try:
        return str(p.relative_to(SRC)).lower()
    except Exception:
        return str(p).lower()

def system_from_name_hint(p):
    low=hint_text(p)
    for hints,system in NAME_HINTS:
        if any(h in low for h in hints):
            return system
    return None

def system_from_hint(p):
    low=hint_text(p)
    for hints,system in DISC_HINTS:
        if any(h in low for h in hints):
            return system
    return None

def unique_dest(destdir, name):
    out=destdir/name
    if not out.exists():
        return out
    stem=Path(name).stem
    suffix=Path(name).suffix
    n=2
    while True:
        alt=destdir/f"{stem}-{n}{suffix}"
        if not alt.exists():
            return alt
        n+=1

def copy_one(src, system):
    global copied, exists, review
    src=Path(src)
    if not src.is_file():
        return
    key=str(src.resolve())
    if key in handled:
        return
    handled.add(key)

    destdir=ROOT/system
    destdir.mkdir(parents=True, exist_ok=True)
    out=destdir/src.name

    if out.exists():
        try:
            if out.stat().st_size == src.stat().st_size:
                print(f" = já existe: {system}/{src.name}")
                exists += 1
                return
        except Exception:
            pass
        out=unique_dest(destdir,src.name)

    shutil.copy2(src,out)
    print(f" + {system}/{out.name}")
    copied += 1
    if system=="_revisar":
        review += 1

def copy_bytes(data, name, system):
    global copied, exists, review, expanded
    destdir=ROOT/system
    destdir.mkdir(parents=True,exist_ok=True)
    out=destdir/Path(name).name

    if out.exists():
        # Para coleções repetidas, não duplica pelo mesmo nome.
        print(f" = já existe: {system}/{out.name}")
        exists += 1
        return

    with open(out,"wb") as f:
        f.write(data)
    print(f" + {system}/{out.name}  [extraído do pacote]")
    copied += 1
    expanded += 1
    if system=="_revisar":
        review += 1

def copy_group(main, members, system):
    copy_one(main,system)
    for p in members:
        copy_one(p,system)

def parse_cue(cue):
    out=[]
    try:
        for line in cue.read_text(errors="ignore").splitlines():
            m=re.match(r'^\s*FILE\s+(?:"([^"]+)"|(\S+))',line,re.I)
            if m:
                name=m.group(1) or m.group(2)
                p=cue.parent/name
                if p.exists():
                    out.append(p)
    except Exception:
        pass
    return out

def parse_gdi(gdi):
    out=[]
    try:
        for line in gdi.read_text(errors="ignore").splitlines()[1:]:
            try:
                parts=shlex.split(line)
            except Exception:
                parts=line.split()
            if len(parts)>=5:
                p=gdi.parent/parts[4]
                if p.exists():
                    out.append(p)
    except Exception:
        pass
    return out

def valid_zip(p):
    try:
        with zipfile.ZipFile(p) as z:
            return z.testzip() is None
    except Exception:
        return False

def valid_7z(p):
    try:
        r=subprocess.run(
            ["7z","t","-y",str(p)],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=300
        )
        return r.returncode==0
    except Exception:
        return False

def archive_names(p):
    names=[]
    try:
        if p.suffix.lower()==".zip":
            with zipfile.ZipFile(p) as z:
                names=[n for n in z.namelist() if not n.endswith("/")]
        else:
            data=subprocess.check_output(
                ["7z","l","-slt",str(p)],
                text=True,errors="ignore",stderr=subprocess.DEVNULL
            )
            for line in data.splitlines():
                if line.startswith("Path = "):
                    n=line[7:].strip()
                    if n and n not in (str(p),p.name):
                        names.append(n)
    except Exception:
        pass
    return names

def detect_archive(p):
    names=archive_names(p)
    exts=[Path(n).suffix.lower() for n in names]
    has_cue=".cue" in exts

    if ".32x" in exts or "32x" in p.name.lower():
        return "sega32x"

    counts={}
    for ext in exts:
        if ext==".bin":
            if has_cue:
                continue
            system="megadrive"
        else:
            system=EXT_SYSTEM.get(ext)
        if system:
            counts[system]=counts.get(system,0)+1

    if counts:
        return max(counts,key=counts.get)

    return system_from_name_hint(p) or system_from_hint(p) or "_revisar"

def detect_disc_single(p):
    return system_from_hint(p) or system_from_name_hint(p) or "_revisar"

def maybe_expand_collection_zip(p):
    """Pacote externo contendo vários jogos compactados/ROMs."""
    global broken
    if not valid_zip(p):
        broken += 1
        broken_files.append(str(p))
        print(f" ! INCOMPLETO/CORROMPIDO, mantido na origem: {p.name}")
        handled.add(str(p.resolve()))
        return True

    outer_system=system_from_name_hint(p)
    try:
        with zipfile.ZipFile(p) as z:
            infos=[i for i in z.infolist() if not i.is_dir()]
            if not infos:
                return False

            inner_zip=[i for i in infos if Path(i.filename).suffix.lower()==".zip"]
            direct_rom=[i for i in infos if Path(i.filename).suffix.lower() in EXT_SYSTEM]

            # Exemplo: "Sega - Master System.zip" -> 50 jogos .zip.
            # Exige uma pista confiável no nome/caminho do pacote.
            if outer_system and outer_system!="_revisar" and len(inner_zip)>=2:
                print(f" > coleção detectada: {p.name} -> {outer_system} ({len(inner_zip)} jogos)")
                for info in inner_zip:
                    try:
                        copy_bytes(z.read(info),Path(info.filename).name,outer_system)
                    except Exception as e:
                        print(f" ! falha ao extrair {info.filename}: {e}")
                handled.add(str(p.resolve()))
                return True

            # Pacote externo com ROMs diretas do mesmo sistema.
            if outer_system and outer_system!="_revisar" and len(direct_rom)>=2:
                compatible=[]
                for info in direct_rom:
                    ext=Path(info.filename).suffix.lower()
                    sys2=EXT_SYSTEM.get(ext)
                    if sys2==outer_system:
                        compatible.append(info)
                if len(compatible)>=2:
                    print(f" > coleção detectada: {p.name} -> {outer_system} ({len(compatible)} ROMs)")
                    for info in compatible:
                        copy_bytes(z.read(info),Path(info.filename).name,outer_system)
                    handled.add(str(p.resolve()))
                    return True
    except Exception:
        return False

    return False

files=[
    p for p in SRC.rglob("*")
    if p.is_file()
    and ".part" not in p.parts
    and "completos" not in p.parts
]

# 1) Conjuntos de disco.
for p in files:
    ext=p.suffix.lower()
    if ext==".cue":
        members=parse_cue(p)
        system=system_from_hint(p) or "_revisar"
        copy_group(p,members,system)
    elif ext==".gdi":
        members=parse_gdi(p)
        system=system_from_hint(p) or "dreamcast"
        copy_group(p,members,system)

# 2) Arquivos independentes/compactados.
for p in files:
    if str(p.resolve()) in handled:
        continue

    ext=p.suffix.lower()

    if ext==".zip":
        if maybe_expand_collection_zip(p):
            continue
        # ZIP normal de jogo: preserva compactado.
        copy_one(p,detect_archive(p))

    elif ext==".7z":
        if not valid_7z(p):
            broken += 1
            broken_files.append(str(p))
            print(f" ! INCOMPLETO/CORROMPIDO, mantido na origem: {p.name}")
            handled.add(str(p.resolve()))
            continue
        copy_one(p,detect_archive(p))

    elif ext in EXT_SYSTEM:
        copy_one(p,EXT_SYSTEM[ext])

    elif ext in (".iso",".chd"):
        copy_one(p,detect_disc_single(p))

    elif ext==".bin":
        copy_one(p,system_from_hint(p) or "_revisar")

    elif ext in (".cue",".gdi"):
        pass

print()
print("==============================================")
print("Importação concluída")
print("==============================================")
print(f"Copiados/extraídos: {copied}")
print(f"Pacotes expandidos: {expanded}")
print(f"Já existentes:      {exists}")
print(f"Para revisão:       {review}")
print(f"Incompletos:        {broken}")
if broken_files:
    print()
    print("Downloads incompletos/corrompidos (preservados na origem):")
    for f in broken_files:
        print(f" - {f}")
print()
print(f"ROMs:    {ROOT}")
print(f"Origem:  {SRC}")
PYEOF

  ok "Importação concluída. Reabra o ES-DE/JottaBox Retrô para atualizar a biblioteca."
}


download_roms_from_root() {
  ensure_dirs

  local download_dir="$HOME_DIR/Downloads/rom"
  local log_file="$HOME_DIR/jotabox-download.log"
  local root_url=""
  local host=""

  mkdir -p "$download_dir"

  echo
  echo "============================================================"
  echo " JottaBox - Downloader"
  echo "============================================================"
  echo
  echo "O downloader SOMENTE baixa para:"
  echo "  $download_dir"
  echo
  echo "Depois use 'Importar jogos' para organizar ~/ROMs."
  echo "Use somente fontes que você tenha autorização para baixar."
  echo

  read -r -p "Digite a URL raiz: " root_url
  [[ -n "$root_url" ]] || die "URL vazia."
  [[ "$root_url" =~ ^https?:// ]] || die "A URL deve começar com http:// ou https://"

  host="$(python3 - "$root_url" <<'PYEOF'
from urllib.parse import urlparse
import sys
print(urlparse(sys.argv[1]).hostname or "")
PYEOF
)"
  [[ -n "$host" ]] || die "Não consegui identificar o domínio da URL."

  say "Baixando para $download_dir"

  set +e
  (
    cd "$download_dir"
    wget \
      --recursive \
      --no-parent \
      --continue \
      --tries=3 \
      --timeout=30 \
      --read-timeout=30 \
      --waitretry=5 \
      --reject "index.html*" \
      --accept "zip,7z,nes,sfc,smc,gb,gbc,gba,nds,n64,z64,v64,md,gen,smd,32x,sms,gg,pce,a26,a52,a78,lnx,ngp,ngc,ws,wsc,cue,bin,gdi,chd,iso,cso,pbp,cdi,rvz,gcm,gcz,wbfs" \
      "$root_url" 2>&1 | tee -a "$log_file"
    exit "${PIPESTATUS[0]}"
  )
  local wget_status=$?
  set -e

  echo
  if [[ "$wget_status" -eq 0 || "$wget_status" -eq 8 ]]; then
    ok "Download encerrado. Arquivos permanecem em $download_dir"
  else
    warn "Download interrompido (código $wget_status). Rode novamente para continuar."
  fi
  echo "Log: $log_file"
  echo
  echo "Quando terminar, use: Biblioteca -> Importar jogos"
}


clean_one() {
  local system="$1"
  local mode="${2:-aggressive}"
  local src="$ROM_ROOT/$system"

  [[ -d "$src" ]] || return 0

  local archive="$ROM_ROOT/_arquivo/$system/$(date +%Y%m%d-%H%M%S)"
  mkdir -p "$archive"

  say "Limpando $system ($mode) sem apagar arquivos"

  python3 - "$src" "$archive" "$mode" <<'PYEOF'
import os,re,sys,shutil
src,archive,mode=sys.argv[1:4]

files=[f for f in os.listdir(src) if os.path.isfile(os.path.join(src,f))]
if not files:
    print("Nenhum arquivo.")
    raise SystemExit

# Tags comuns em sets GoodTools/No-Intro antigos.
bad_patterns=[
    r"\[b\d*[^\]]*\]",      # bad dump
    r"\[h\d*[^\]]*\]",      # hack
    r"\[t\d*[^\]]*\]",      # trainer
    r"\[o\d*[^\]]*\]",      # overdump
]

bad_words=[
    "beta",
    "pre-release",
    "prerelease",
    "prototype",
    "proto",
    "(rus)",
    "(chinese)",
    "[t+rus",
    "[t-rus",
    "[t+chi",
    "[t-chi",
]

# Formatos que costumam ser arquivo único e podem ser movidos
# com segurança em sistemas de disco.
single_file_exts={
    ".zip",".7z",".chd",".pbp",".cso",".iso",".cdi",
    ".nes",".sfc",".smc",".md",".gen",".32x",".sms",".gg",
    ".gb",".gbc",".gba",".z64",".n64",".v64"
}

# Arquivos que podem fazer parte de jogos multi-arquivo:
# não mover isoladamente no modo conservador.
protected_multi_exts={
    ".cue",".bin",".gdi",".raw",".wav",".ccd",".img",".sub",".mds",".mdf"
}

def unwanted(name):
    low=name.lower()
    if any(x in low for x in bad_words):
        return True
    return any(re.search(p,name,re.I) for p in bad_patterns)

def norm_key(name):
    s=os.path.splitext(name)[0]
    # Mantém traduções PT como versão separada preferencial.
    is_pt=bool(re.search(r"(t\+por|pt[-_ ]?br|portugu)",s,re.I))
    s=re.sub(r"\[[^\]]+\]"," ",s)
    s=re.sub(
        r"\([^)]*(?:U|USA|E|Europe|J|Japan|World|W|UE|JU|JUE|EUJ|Brazil|Brasil)[^)]*\)",
        " ",s,flags=re.I
    )
    s=re.sub(r"\b(?:REV|REVISION)\s*\d+\b"," ",s,flags=re.I)
    s=re.sub(r"[\s._-]+"," ",s).strip().lower()
    return ("pt:" if is_pt else "") + s

def score(name):
    low=name.lower()
    sc=0
    if "[t+por" in low or "pt-br" in low or "ptbr" in low or "portugu" in low:
        sc += 100
    if "[!]" in low:
        sc += 50
    if "(u)" in low or "(usa)" in low or "(us)" in low:
        sc += 25
    elif "world" in low:
        sc += 20
    elif "(e)" in low or "(europe)" in low:
        sc += 15
    elif "(j)" in low or "(japan)" in low:
        sc += 5
    # Menos tags = nome mais limpo.
    sc -= name.count("[")
    sc -= name.count("(") * 0.2
    return sc

def safe_move(name, reason):
    global moved
    srcp=os.path.join(src,name)
    dstp=os.path.join(archive,name)
    os.makedirs(os.path.dirname(dstp),exist_ok=True)
    shutil.move(srcp,dstp)
    moved.append((name,reason))

moved=[]
candidates=[]

# Etapa 1: variantes explicitamente ruins/hacks/betas.
for f in files:
    ext=os.path.splitext(f)[1].lower()

    if not unwanted(f):
        candidates.append(f)
        continue

    # Em sistemas de disco, não movemos pedaços de um conjunto
    # multi-arquivo para evitar quebrar .cue/.gdi.
    if mode=="conservative" and ext in protected_multi_exts:
        candidates.append(f)
        continue

    if mode=="conservative" and ext not in single_file_exts:
        candidates.append(f)
        continue

    safe_move(f,"variante")

# Etapa 2: deduplicação.
# Só é aplicada fortemente em consoles de cartucho.
if mode=="aggressive":
    groups={}
    for f in candidates:
        groups.setdefault(norm_key(f),[]).append(f)

    for key,group in groups.items():
        if not key or len(key)<3 or len(group)<2:
            continue

        group=sorted(group,key=lambda x:(score(x),-len(x)),reverse=True)

        # Mantém a versão preferida.
        for f in group[1:]:
            if os.path.exists(os.path.join(src,f)):
                safe_move(f,"duplicata")

before=len(files)
after=len([f for f in os.listdir(src) if os.path.isfile(os.path.join(src,f))])

print("Antes:",before)
print("Mantidos:",after)
print("Arquivados:",len(moved))
print("Arquivo:",archive)
PYEOF
}

detect_clean_mode() {
  local dir="$1"

  python3 - "$dir" <<'PYEOF'
import os,sys
d=sys.argv[1]

aggressive={
    ".nes",".sfc",".smc",".md",".gen",".32x",".sms",".gg",
    ".gb",".gbc",".gba",".z64",".n64",".v64",".a26",".a52",
    ".a78",".lnx",".ngp",".ngc",".pce",".sg",".col",".vec"
}
conservative={
    ".cue",".bin",".gdi",".iso",".chd",".cso",".pbp",".cdi",
    ".img",".ccd",".sub",".mds",".mdf",".raw",".wav",".zip",".7z"
}

a=c=0
try:
    for name in os.listdir(d):
        p=os.path.join(d,name)
        if not os.path.isfile(p):
            continue
        ext=os.path.splitext(name)[1].lower()
        if ext in aggressive: a += 1
        if ext in conservative: c += 1
except Exception:
    print("unknown")
    raise SystemExit

if a > 0 and a >= c:
    print("aggressive")
elif c > 0:
    print("conservative")
else:
    print("unknown")
PYEOF
}

discover_rom_system_dirs() {
  find "$ROM_ROOT" \
    -mindepth 1 -maxdepth 1 \
    -type d \
    ! -name '_arquivo' \
    ! -name '_revisar' \
    ! -name 'downloaded_media' \
    ! -name 'media' \
    ! -name 'screenshots' \
    ! -name 'videos' \
    ! -name 'covers' \
    ! -name 'miximages' \
    ! -name 'marquees' \
    ! -name 'thumbnails' \
    -print0
}

clean_roms() {
  ensure_dirs
  local target="${1:-all}"

  if [[ "$target" == "all" ]]; then
    local count=0 skipped=0
    while IFS= read -r -d '' dir; do
      local system mode
      system="$(basename "$dir")"
      mode="$(detect_clean_mode "$dir")"

      case "$mode" in
        aggressive|conservative)
          clean_one "$system" "$mode"
          count=$((count+1))
          ;;
        *)
          warn "Ignorando '$system': formato não reconhecido para limpeza segura."
          skipped=$((skipped+1))
          ;;
      esac
    done < <(discover_rom_system_dirs)

    ok "Limpeza dinâmica concluída: $count pasta(s) processada(s), $skipped ignorada(s)."
    return
  fi

  local dir="$ROM_ROOT/$target"
  [[ -d "$dir" ]] || die "Pasta de ROM não encontrada: $dir"

  local mode
  mode="$(detect_clean_mode "$dir")"

  case "$mode" in
    aggressive|conservative)
      clean_one "$target" "$mode"
      ;;
    *)
      die "Não consegui determinar um modo seguro de limpeza para: $target"
      ;;
  esac
}

status_report() {
  ensure_dirs

  echo "============================================================"
  echo " JottaBox GAME SUITE $VERSION"
  echo "============================================================"
  echo

  printf "%-22s %10s %14s\n" "Pasta" "Arquivos" "Modo limpeza"
  printf "%-22s %10s %14s\n" "-----" "--------" "------------"

  while IFS= read -r -d '' dir; do
    system="$(basename "$dir")"
    count="$(find "$dir" -maxdepth 1 -type f 2>/dev/null | wc -l)"
    mode="$(detect_clean_mode "$dir")"
    printf "%-22s %10s %14s\n" "$system" "$count" "$mode"
  done < <(discover_rom_system_dirs)

  echo
  echo "_revisar: $(find "$ROM_ROOT/_revisar" -maxdepth 1 -type f 2>/dev/null | wc -l)"
  echo "_arquivo: $(find "$ROM_ROOT/_arquivo" -type f 2>/dev/null | wc -l)"
  echo

  flatpak list | grep -Ei 'RetroArch|PCSX2|Dolphin|PPSSPP|Steam' || true

  echo
  echo -n "Cores RetroArch: "
  find "$HOME_DIR/.var/app/org.libretro.RetroArch/config/retroarch/cores" \
    -maxdepth 1 -type f -name '*_libretro.so' 2>/dev/null | wc -l

  [[ -x "$APP_DIR/ES-DE_x64.AppImage" ]] && echo "ES-DE: OK" || echo "ES-DE: AUSENTE"
  command -v microsoft-edge-stable >/dev/null && echo "Edge: OK" || echo "Edge: AUSENTE"

  echo
  echo "Motor JottaBox:"
  if [[ -x "$ENGINE" ]]; then
    echo "  OK: $ENGINE"
    "$ENGINE" --version 2>/dev/null | sed 's/^/  Versão: /' || true
  else
    echo "  AUSENTE: $ENGINE"
  fi

  storage_status
  echo
  echo "Atalhos:"
  for w in jottabox-import-roms jottabox-clean-roms jottabox-update jottabox-status jottabox-repair-hotkey jottabox-configure-controller jottabox-controller-diagnostics jottabox-storage jottabox-download-roms jottabox-console; do
    if [[ -x "$BIN_DIR/$w" ]]; then
      printf "  OK %-28s" "$w"
      if grep -q '/tmp/jottabox' "$BIN_DIR/$w" 2>/dev/null; then
        echo " ERRO: aponta para /tmp"
      else
        echo
      fi
    else
      echo "  AUSENTE $w"
    fi
  done
}

do_install() {
  ensure_dirs
  apt_base
  setup_flathub
  install_apps
  install_edge
  install_esde
  install_cores
  configure_retroarch
  install_engine
  create_wrappers
  create_hotkey_watchdog
  create_controller_wizard
  create_controller_diagnostics
  install_visual_assets
  create_downloader_gui
  create_launcher
  configure_console_mode

  ok "Instalação completa finalizada"
  echo
  echo "Teste:"
  echo "  $BIN_DIR/jottabox-console"
}

do_update() {
  say "Atualizando sistema"
  apt_base
  setup_flathub
  sudo apt upgrade -y
  sudo flatpak update --system -y
  install_edge
  install_esde
  install_cores
  configure_retroarch
  install_engine
  create_wrappers
  create_hotkey_watchdog
  create_controller_wizard
  create_controller_diagnostics
  install_visual_assets
  create_downloader_gui
  create_launcher

  ok "Atualização concluída"
}

repair_wrappers() {
  install_engine
  create_wrappers
  create_hotkey_watchdog
  create_controller_wizard
  create_controller_diagnostics
  create_downloader_gui
  create_launcher
  ok "Atalhos e serviços JottaBox reparados"
}

menu() {
  while true; do
    clear
    echo "============================================================"
    echo " JottaBox GAME CONSOLE SUITE $VERSION"
    echo "============================================================"
    echo "1) Instalação completa / reparar"
    echo "2) Atualizar tudo"
    echo "3) Importar/organizar ROMs de ~/Downloads/rom"
    echo "4) Limpar/organizar TODAS as pastas detectadas em ~/ROMs"
    echo "5) Instalar/reparar cores RetroArch"
    echo "6) Ver status"
    echo "7) Abrir launcher"
    echo "8) Reparar hotkey SELECT + START"
    echo "9) Baixar por URL raiz para ~/Downloads/rom"
    echo "10) Reparar motor/atalhos JottaBox"
    echo "11) Armazenamento interno / HD externo"
    echo "0) Sair"
    echo
    read -rp "Escolha: " op

    case "$op" in
      1) do_install ;;
      2) do_update ;;
      3) import_roms "$HOME_DIR/Downloads/rom" ;;
      4) clean_roms all ;;
      5) install_cores; configure_retroarch ;;
      6) status_report ;;
      7) "$BIN_DIR/jottabox-console" ;;
      8) create_hotkey_watchdog; configure_retroarch ;;
      9) download_roms_from_root ;;
      10) repair_wrappers ;;
      11) storage_manager ;;
      0) exit 0 ;;
      *) echo "Opção inválida" ;;
    esac

    echo
    read -rp "ENTER para continuar..." _
  done
}

case "${1:-menu}" in
  install) do_install ;;
  update) do_update ;;
  import) import_roms "${2:-$HOME_DIR/Downloads/rom}" ;;
  clean) clean_roms "${2:-all}" ;;
  cores) install_cores; configure_retroarch ;;
  status) status_report ;;
  launcher) "$BIN_DIR/jottabox-console" ;;
  download) download_roms_from_root ;;
  repair-hotkey) create_hotkey_watchdog; configure_retroarch ;;
  repair-wrappers) repair_wrappers ;;
  storage) storage_manager ;;
  storage-check) storage_check ;;
  menu) menu ;;
  --version|-v) echo "$VERSION" ;;
  *)
    echo "Uso:"
    echo "  $0 install"
    echo "  $0 update"
    echo "  $0 import [pasta]"
    echo "  $0 clean [sistema|all]"
    echo "  $0 cores"
    echo "  $0 status"
    echo "  $0 launcher"
    echo "  $0 download"
    echo "  $0 repair-hotkey"
    echo "  $0 repair-wrappers"
    echo "  $0 storage"
    echo "  $0 storage-check"
    echo "  $0 menu"
    exit 2
    ;;
esac
